const EXAM_BANK={"source":"claude/story-planning 190eadb","files":[{"path":"exam_official/admin20_2026-10-14.json","taken":20},{"path":"exam_official/civil40_2026-10-14.json","taken":40},{"path":"exam_official/civil_supp40_2026-10-14.json","taken":40},{"path":"exam_official/criminal45_2026-10-14.json","taken":45},{"path":"exam_official/securities40_2026-10-14.json","taken":40},{"path":"exam_y4/AA_crim_judgment_sem.json","taken":8},{"path":"exam_y4/AA_enforcement.json","taken":8},{"path":"exam_y4/AA_labor_social.json","taken":2},{"path":"exam_y4/AA_legal_ethics.json","taken":8},{"path":"exam_y4/AA_maritime.json","taken":2},{"path":"exam_y4/AA_public_judgment_sem.json","taken":8},{"path":"exam_y4/AA_tax_law.json","taken":3},{"path":"exam_y4/BB_ip_law.json","taken":13},{"path":"exam_y4/BB_labor_social.json","taken":13},{"path":"exam_y4/BB_maritime.json","taken":11},{"path":"exam_y4/BB_tax_law.json","taken":12}],"questions":[{"id":"ADM20_01","course":"admin_law","term":"Y2S1","scopeWeek":2,"type":"mc","q":"行政機關限制人民基本權利時，原則上須有法律或法律明確授權的依據。此要求主要體現何種原則？","options":{"A":"信賴保護原則","B":"法律保留原則","C":"行政自我拘束原則","D":"不當聯結禁止原則"},"answer":"B","core":"行政法總論・法律保留","explanation":"","basis":"","status":"USER_CONFIRMED","source":"行政法_20題_2026-10-14.md 第 1 題"},{"id":"ADM20_02","course":"admin_law","term":"Y2S1","scopeWeek":2,"type":"mc","q":"依行政程序法第7條，行政機關採取限制人民權利的措施時，下列何者不是比例原則的審查內容？","options":{"A":"適當性","B":"必要性","C":"狹義比例性","D":"行政機關是否能獲得最大財政收入"},"answer":"D","core":"比例原則","explanation":"","basis":"行政程序法 §7","status":"USER_CONFIRMED","source":"行政法_20題_2026-10-14.md 第 2 題"},{"id":"ADM20_03","course":"admin_law","term":"Y2S1","scopeWeek":5,"type":"mc","q":"依行政程序法第92條，下列何者最符合行政處分的概念？","options":{"A":"機關內部的人事工作分配","B":"行政機關對外就具體事件所為、直接發生法律效果的單方公權力措施","C":"行政機關與人民簽訂的所有私法契約","D":"公務員私下提出的法律意見"},"answer":"B","core":"行政處分的認定","explanation":"","basis":"行政程序法 §92","status":"USER_CONFIRMED","source":"行政法_20題_2026-10-14.md 第 3 題"},{"id":"ADM20_04","course":"admin_law","term":"Y2S1","scopeWeek":12,"type":"mc","q":"依行政程序法第111條第7款，行政處分具有何種瑕疵時，可能構成無效？","options":{"A":"任何輕微文字錯誤","B":"當事人不同意行政機關的判斷","C":"重大而且明顯的瑕疵","D":"行政處分未附上新聞稿"},"answer":"C","core":"行政處分的無效","explanation":"","basis":"行政程序法 §111 ⑦","status":"USER_CONFIRMED","source":"行政法_20題_2026-10-14.md 第 4 題"},{"id":"ADM20_05","course":"admin_law","term":"Y2S1","scopeWeek":12,"type":"mc","q":"依行政程序法第117條，下列何者最正確？","options":{"A":"違法行政處分一律不得撤銷","B":"原處分機關或其上級機關在法定限制下，得依職權撤銷違法行政處分","C":"只有行政法院能撤銷違法行政處分","D":"只要違法行政處分有利於人民，就絕對不能撤銷"},"answer":"B","core":"行政處分的撤銷","explanation":"","basis":"行政程序法 §117","status":"USER_CONFIRMED","source":"行政法_20題_2026-10-14.md 第 5 題"},{"id":"ADM20_06","course":"admin_law","term":"Y2S1","scopeWeek":12,"type":"mc","q":"依行政程序法第119條，下列何者屬於信賴不值得保護的法定情形？","options":{"A":"受益人因行政機關錯誤而取得處分，且完全不知情亦無重大過失","B":"受益人已依處分安排生活","C":"受益人以詐欺方法使行政機關作成處分","D":"受益人收到行政機關寄發的正式處分書"},"answer":"C","core":"信賴保護","explanation":"","basis":"行政程序法 §119 ①","status":"USER_CONFIRMED","source":"行政法_20題_2026-10-14.md 第 6 題"},{"id":"ADM20_07","course":"admin_law","term":"Y2S1","scopeWeek":7,"type":"mc","q":"行政機關擬作成限制人民權利的行政處分時，依行政程序法第102條，原則上應給予當事人何種程序保障？","options":{"A":"陳述意見的機會","B":"自行指定承辦公務員的權利","C":"要求行政機關無條件接受其主張","D":"直接要求行政法院作成判決"},"answer":"A","core":"行政程序・陳述意見","explanation":"","basis":"行政程序法 §102","status":"USER_CONFIRMED","source":"行政法_20題_2026-10-14.md 第 7 題"},{"id":"ADM20_08","course":"admin_law","term":"Y2S1","scopeWeek":7,"type":"mc","q":"依行政程序法第114條，下列何種程序瑕疵，在法定條件及期限內可能補正？","options":{"A":"欠缺法定行政處分權限的所有情形","B":"應給予當事人陳述意見機會而未給予，事後補給機會","C":"重大明顯瑕疵一律因補正而有效","D":"違反任何實體法要件"},"answer":"B","core":"行政程序瑕疵的補正","explanation":"","basis":"行政程序法 §114 I ③","status":"USER_CONFIRMED","source":"行政法_20題_2026-10-14.md 第 8 題"},{"id":"ADM20_09","course":"admin_law","term":"Y2S1","scopeWeek":6,"type":"mc","q":"依行政程序法第135條，公法上法律關係原則上得以何種方式設定、變更或消滅，但依性質或法規規定不得締約者除外？","options":{"A":"行政契約","B":"刑事判決","C":"私人遺囑","D":"民事假扣押"},"answer":"A","core":"行政契約","explanation":"","basis":"行政程序法 §135","status":"USER_CONFIRMED","source":"行政法_20題_2026-10-14.md 第 9 題"},{"id":"ADM20_10","course":"admin_law","term":"Y2S1","scopeWeek":10,"type":"mc","q":"依行政罰法第7條第1項，違反行政法上義務的行為，若非出於故意或過失，原則上如何處理？","options":{"A":"一律處最高額罰鍰","B":"仍應無條件處罰","C":"不予處罰","D":"必須移送刑事法院"},"answer":"C","core":"行政罰・責任條件","explanation":"","basis":"行政罰法 §7 I","status":"USER_CONFIRMED","source":"行政法_20題_2026-10-14.md 第 10 題"},{"id":"ADM20_11","course":"admin_law","term":"Y2S1","scopeWeek":10,"type":"mc","q":"依行政罰法第24條第1項，一行為違反數個行政法上義務規定而均應處罰鍰時，原則上如何裁處？","options":{"A":"各罰鍰全部累加，絕無例外","B":"依法定罰鍰額最高的規定裁處，並受法定最低額等限制","C":"一律不處罰","D":"交由人民自行選擇處罰依據"},"answer":"B","core":"行政罰・一行為不二罰","explanation":"","basis":"行政罰法 §24 I","status":"USER_CONFIRMED","source":"行政法_20題_2026-10-14.md 第 11 題"},{"id":"ADM20_12","course":"admin_law","term":"Y2S1","scopeWeek":10,"type":"mc","q":"判斷按日連續處罰的法律性質與適法性時，最應注意何者？","options":{"A":"只要法律出現「按日」二字，就必然完全不受行政罰法拘束","B":"只看處分書的名稱","C":"應檢視法規目的、義務內容、改善期限與各次違反行為的關係","D":"每次處罰都必須先有刑事判決"},"answer":"C","core":"按日連續處罰","explanation":"","basis":"","status":"USER_CONFIRMED","source":"行政法_20題_2026-10-14.md 第 12 題"},{"id":"ADM20_13","course":"admin_law","term":"Y2S1","scopeWeek":14,"type":"mc","q":"依行政執行法，對於依法負有可代替行為以外的行為義務或不行為義務者，在法定條件下得採取何種間接強制方法？","options":{"A":"怠金","B":"死刑","C":"沒收全部財產","D":"民事假處分"},"answer":"A","core":"行政執行・怠金","explanation":"","basis":"行政執行法 §28 I、§30","status":"USER_CONFIRMED","source":"行政法_20題_2026-10-14.md 第 13 題"},{"id":"ADM20_14","course":"admin_law","term":"Y2S1","scopeWeek":14,"type":"mc","q":"甲依法負有拆除違法設施的義務，逾期不履行，該義務可以由第三人代為完成。行政機關在法定條件下得考慮何種方法？","options":{"A":"直接判處有期徒刑","B":"代履行","C":"撤銷甲的國籍","D":"宣告甲的全部契約無效"},"answer":"B","core":"行政執行・代履行","explanation":"","basis":"行政執行法 §28 I、§29","status":"USER_CONFIRMED","source":"行政法_20題_2026-10-14.md 第 14 題"},{"id":"ADM20_15","course":"admin_remedy","term":"Y2S2","scopeWeek":3,"type":"mc","q":"關於訴願程序中的不利益變更禁止，下列何者最接近其核心意義？","options":{"A":"訴願機關永遠不得撤銷原處分","B":"提起救濟者不得因救濟決定而受到較原處分更不利的變更","C":"訴願人提出的理由必須全部成立","D":"行政機關不得作成任何新處分"},"answer":"B","core":"訴願・不利益變更禁止","explanation":"","basis":"訴願法 §81 I 但書","status":"USER_CONFIRMED","source":"行政法_20題_2026-10-14.md 第 15 題"},{"id":"ADM20_16","course":"admin_remedy","term":"Y2S2","scopeWeek":5,"type":"mc","q":"人民認為行政機關作成的行政處分違法，侵害其權利或法律上利益，經必要的訴願程序後，原則上得提起何種訴訟？","options":{"A":"撤銷訴訟","B":"刑事自訴","C":"民事確認親子關係訴訟","D":"非訟事件"},"answer":"A","core":"行政訴訟・撤銷訴訟","explanation":"","basis":"行政訴訟法 §4 I","status":"USER_CONFIRMED","source":"行政法_20題_2026-10-14.md 第 16 題"},{"id":"ADM20_17","course":"admin_remedy","term":"Y2S2","scopeWeek":6,"type":"mc","q":"甲依法申請核發許可，行政機關違法駁回。甲希望法院促使行政機關依法作成所申請的行政處分，原則上應考慮何種訴訟？","options":{"A":"撤銷婚姻訴訟","B":"課予義務訴訟","C":"刑事再審","D":"確認所有權訴訟"},"answer":"B","core":"行政訴訟・課予義務訴訟","explanation":"","basis":"行政訴訟法 §5 II","status":"USER_CONFIRMED","source":"行政法_20題_2026-10-14.md 第 17 題"},{"id":"ADM20_18","course":"admin_law","term":"Y2S1","scopeWeek":11,"type":"mc","q":"依最高法院111年度台上大字第1706號民事裁定，關於國家賠償法第2條第2項前段所保護的客體，下列何者正確？","options":{"A":"僅限民法第184條第1項前段所稱權利","B":"一律排除純粹經濟上損失","C":"不以權利為限，符合要件的利益損害亦可能受保護","D":"僅限身體及生命權"},"answer":"C","core":"國家賠償・純粹經濟上損失","explanation":"","basis":"國家賠償法 §2 II","status":"USER_CONFIRMED","source":"行政法_20題_2026-10-14.md 第 18 題"},{"id":"ADM20_19","course":"admin_law","term":"Y2S1","scopeWeek":11,"type":"mc","q":"依國家賠償法第3條第1項，公共設施設置或管理有欠缺，致人民生命、身體、人身自由或財產受損害時，原則上由何者負賠償責任？","options":{"A":"受害人自行承擔全部損失","B":"國家","C":"一律由現場公務員個人賠償","D":"只能向私人保險公司請求"},"answer":"B","core":"國家賠償・公共設施","explanation":"","basis":"國家賠償法 §3 I","status":"USER_CONFIRMED","source":"行政法_20題_2026-10-14.md 第 19 題"},{"id":"ADM20_20","course":"admin_remedy","term":"Y2S2","scopeWeek":13,"type":"mc","q":"關於既成道路與公用地役關係的成立，下列何者最符合相關實務見解？","options":{"A":"只要有人曾經通行一次即可成立","B":"私有土地一旦有人通行，所有權立即移轉給國家","C":"須依供公眾通行的必要性、長期通行事實及其他實務所定要件判斷","D":"只要行政機關口頭宣稱即可成立"},"answer":"C","core":"公用地役關係","explanation":"","basis":"","status":"USER_CONFIRMED","source":"行政法_20題_2026-10-14.md 第 20 題"},{"id":"CIV40_01","course":"civ_general","term":"Y1S1","scopeWeek":14,"type":"mc","q":"甲遭乙以詐欺方式誘使訂立買賣契約。依民法第92條，甲原則上得主張何種法律效果？","options":{"A":"契約當然無效","B":"撤銷意思表示","C":"契約自動解除","D":"僅得請求精神慰撫金"},"answer":"B","core":"民法總則・意思表示","explanation":"詐欺原則上使表意人取得撤銷權，而非當然無效。第三人詐欺等情形仍須注意特別要件。","basis":"民法 §92","status":"USER_CONFIRMED","source":"民法_40題_2026-10-14.md 第 1 題"},{"id":"CIV40_02","course":"civ_general","term":"Y1S1","scopeWeek":16,"type":"mc","q":"依民法第144條第1項，消滅時效完成後，債務人取得何種法律地位？","options":{"A":"債權自動消滅","B":"契約當然無效","C":"得拒絕給付","D":"債權移轉於國家"},"answer":"C","core":"民法總則・消滅時效","explanation":"時效完成並非債權當然消滅，而是債務人取得拒絕給付的抗辯權。","basis":"民法 §144 I","status":"USER_CONFIRMED","source":"民法_40題_2026-10-14.md 第 2 題"},{"id":"CIV40_03","course":"civ_general","term":"Y1S1","scopeWeek":15,"type":"mc","q":"甲未經乙授權，卻以乙的名義與丙締結契約。依民法第170條，契約對乙的效力原則上如何？","options":{"A":"當然有效","B":"經乙承認，始對乙發生效力","C":"當然無效且不得補正","D":"直接對甲與乙共同生效"},"answer":"B","core":"民法總則・無權代理","explanation":"無權代理行為原則上效力未定，取決於本人是否承認。","basis":"民法 §170 I","status":"USER_CONFIRMED","source":"民法_40題_2026-10-14.md 第 3 題"},{"id":"CIV40_04","course":"oblig_gen1","term":"Y1S2","scopeWeek":15,"type":"mc","q":"依民法第184條第1項前段的通常理解，下列何者最適合描述純粹經濟上損失？","options":{"A":"身體受傷所生醫療費","B":"所有權受侵害所生修繕費","C":"未伴隨既有權利受侵害的財產利益損失","D":"人格權受侵害所生非財產損害"},"answer":"C","core":"債法總論・純粹經濟上損失","explanation":"純粹經濟上損失涉及「權利」與一般財產利益的區分，是否能請求賠償，還須檢查其他侵權責任構成要件與請求權基礎。","basis":"民法 §184 I","status":"USER_CONFIRMED","source":"民法_40題_2026-10-14.md 第 4 題"},{"id":"CIV40_05","course":"oblig_gen1","term":"Y1S2","scopeWeek":14,"type":"mc","q":"關於法人侵權責任，下列何者較符合現行實務的討論方向？","options":{"A":"法人絕對不可能成立侵權行為","B":"法人僅能負契約責任","C":"法人的組織活動及機關行為可能構成其侵權責任基礎","D":"只要法人有資產就當然成立侵權"},"answer":"C","core":"債法總論・法人侵權","explanation":"不能僅以法人不是自然人，就排除法人侵權責任；仍應依具體責任規範與構成要件判斷。","basis":"民法 §184、§28","status":"USER_CONFIRMED","source":"民法_40題_2026-10-14.md 第 5 題"},{"id":"CIV40_06","course":"oblig_gen2","term":"Y2S1","scopeWeek":5,"type":"mc","q":"甲出售機器給乙，交付的機器有瑕疵，並因可歸責於甲的瑕疵造成乙其他設備損壞。此情形除買賣瑕疵擔保外，可能涉及何種債務不履行類型？","options":{"A":"不完全給付","B":"債權讓與","C":"無因管理","D":"混同"},"answer":"A","core":"債法總論・不完全給付","explanation":"不完全給付可能涉及履行利益及加害給付所生的其他損害，應分別檢查救濟要件。","basis":"民法 §227","status":"USER_CONFIRMED","source":"民法_40題_2026-10-14.md 第 6 題"},{"id":"CIV40_07","course":"oblig_gen2","term":"Y2S1","scopeWeek":16,"type":"mc","q":"關於時效抗辯與誠信原則的關係，下列何者較正確？","options":{"A":"時效完成後，債務人永遠不得主張時效","B":"時效抗辯一律違反誠信原則","C":"時效抗辯原則上可以行使，但特殊情況可能受到誠信原則限制","D":"債權人只要表示不滿，即可排除時效"},"answer":"C","core":"債法總論・誠信原則與時效抗辯","explanation":"不能將誠信原則變成全面否定時效制度的工具，須有具體特殊事實支持。","basis":"民法 §144、§148 II","status":"USER_CONFIRMED","source":"民法_40題_2026-10-14.md 第 7 題"},{"id":"CIV40_08","course":"oblig_gen1","term":"Y1S2","scopeWeek":12,"type":"mc","q":"甲誤將10萬元匯入乙的帳戶，雙方沒有任何債權債務關係。甲最直接可考慮何種請求權？","options":{"A":"民法第179條不當得利返還請求權","B":"民法第767條所有物返還請求權","C":"繼承回復請求權","D":"剩餘財產分配請求權"},"answer":"A","core":"債法總論・不當得利","explanation":"乙無法律上原因受有利益，致甲受損害，應依不當得利要件判斷。","basis":"民法 §179","status":"USER_CONFIRMED","source":"民法_40題_2026-10-14.md 第 8 題"},{"id":"CIV40_09","course":"oblig_spec","term":"Y2S2","scopeWeek":15,"type":"mc","q":"依民法第493條，工作有瑕疵時，定作人原則上首先得請求承攬人如何處理？","options":{"A":"直接支付雙倍報酬","B":"於相當期限內修補瑕疵","C":"無條件解除一切契約","D":"將工作交給法院保管"},"answer":"B","core":"債法各論・承攬瑕疵","explanation":"修補請求權是承攬瑕疵救濟的重要起點，其他救濟須注意各自的法定要件。","basis":"民法 §493 I","status":"USER_CONFIRMED","source":"民法_40題_2026-10-14.md 第 9 題"},{"id":"CIV40_10","course":"oblig_spec","term":"Y2S2","scopeWeek":16,"type":"mc","q":"甲向乙借款10萬元，約定一個月後返還。下列何者最符合消費借貸的基本性質？","options":{"A":"借用人須返還原來同一張鈔票","B":"借用人應返還同種類、品質及數量之物","C":"出借人仍保有已交付金錢的所有權","D":"消費借貸一律無償"},"answer":"B","core":"債法各論・消費借貸","explanation":"消費借貸與使用借貸不同，借用人取得借用物所有權，負返還同種類、品質及數量之物的義務。","basis":"民法 §474、§478","status":"USER_CONFIRMED","source":"民法_40題_2026-10-14.md 第 10 題"},{"id":"CIV40_11","course":"oblig_spec","term":"Y2S2","scopeWeek":4,"type":"mc","q":"出租人於租賃關係存續中，原則上負有何種義務？","options":{"A":"保持租賃物合於約定使用、收益的狀態","B":"保證承租人經營必定獲利","C":"無條件移轉租賃物所有權","D":"永久不得終止租約"},"answer":"A","core":"債法各論・租賃","explanation":"民法第423條規定出租人交付及保持租賃物合於約定使用收益的義務。","basis":"民法 §423","status":"USER_CONFIRMED","source":"民法_40題_2026-10-14.md 第 11 題"},{"id":"CIV40_12","course":"property","term":"Y2S1","scopeWeek":5,"type":"mc","q":"甲為A物所有權人，乙無權占有A物。甲原則上得依何條規定請求返還？","options":{"A":"民法第179條","B":"民法第184條","C":"民法第767條","D":"民法第1030條之1"},"answer":"C","core":"物權・所有物返還請求權","explanation":"所有人對無權占有其所有物者，得請求返還。","basis":"民法 §767 I","status":"USER_CONFIRMED","source":"民法_40題_2026-10-14.md 第 12 題"},{"id":"CIV40_13","course":"property","term":"Y2S1","scopeWeek":4,"type":"mc","q":"動產善意取得制度，主要保護何種利益？","options":{"A":"原所有人永遠不得喪失所有權","B":"動產交易安全與善意受讓人的信賴","C":"任何占有人都能立即取得所有權","D":"所有無償取得人均受完全保護"},"answer":"B","core":"物權・動產善意取得","explanation":"善意取得仍有法定要件，不能僅因受讓人主張不知情即當然成立。","basis":"民法 §801、§948","status":"USER_CONFIRMED","source":"民法_40題_2026-10-14.md 第 13 題"},{"id":"CIV40_14","course":"property","term":"Y2S1","scopeWeek":12,"type":"mc","q":"關於讓與擔保的基本功能，下列何者正確？","options":{"A":"為擔保債權而移轉財產權利","B":"單純無償贈與","C":"必然成立租賃契約","D":"一律禁止債務人清償"},"answer":"A","core":"物權・讓與擔保","explanation":"讓與擔保涉及形式上的權利移轉與實質擔保目的之間的關係。","basis":"（非典型擔保；民法沒有明文）","status":"USER_CONFIRMED","source":"民法_40題_2026-10-14.md 第 14 題"},{"id":"CIV40_15","course":"property","term":"Y2S1","scopeWeek":7,"type":"mc","q":"下列何者最符合公同共有的特徵？","options":{"A":"每位共有人必然有可自由處分的應有部分","B":"公同共有人基於公同關係共有一物","C":"任何第三人都可以單方終止公同關係","D":"公同共有只可能發生在動產"},"answer":"B","core":"物權・公同共有","explanation":"公同共有與分別共有的法律結構不同，權利行使及處分應注意公同關係與法律規定。","basis":"民法 §827","status":"USER_CONFIRMED","source":"民法_40題_2026-10-14.md 第 15 題"},{"id":"CIV40_16","course":"family_law","term":"Y2S2","scopeWeek":12,"type":"mc","q":"依74年6月3日修正前民法第1079條，收養子女原則上應採何種方式？","options":{"A":"口頭約定","B":"書面","C":"公證遺囑","D":"法院調解"},"answer":"B","core":"親屬・收養","explanation":"舊法另有自幼撫養為子女的例外，應與現行收養制度區分。","basis":"民法 §1079（74 年 6 月 3 日修正前）","status":"USER_CONFIRMED","source":"民法_40題_2026-10-14.md 第 16 題"},{"id":"CIV40_17","course":"family_law","term":"Y2S2","scopeWeek":7,"type":"mc","q":"民法第1030條之1所定剩餘財產差額分配，原則上發生於何時？","options":{"A":"雙方第一次約會時","B":"法定財產制關係消滅時","C":"任何一方購買動產時","D":"婚姻登記滿一年時"},"answer":"B","core":"親屬・剩餘財產分配","explanation":"計算時還須注意婚前財產、婚後財產、債務及依法不列入分配的項目。","basis":"民法 §1030-1 I","status":"USER_CONFIRMED","source":"民法_40題_2026-10-14.md 第 17 題"},{"id":"CIV40_18","course":"family_law","term":"Y2S2","scopeWeek":7,"type":"mc","q":"依民法第1030條之1，夫妻一方因繼承取得的婚後財產，原則上如何處理？","options":{"A":"全額列入剩餘財產分配","B":"原則上不列入剩餘財產差額分配","C":"當然歸另一方所有","D":"一律成為夫妻公同共有"},"answer":"B","core":"親屬・夫妻財產","explanation":"繼承、其他無償取得及慰撫金等法定排除項目，應分別辨識。","basis":"民法 §1030-1 I ①","status":"USER_CONFIRMED","source":"民法_40題_2026-10-14.md 第 18 題"},{"id":"CIV40_19","course":"family_law","term":"Y2S2","scopeWeek":13,"type":"mc","q":"依民法第1138條，下列何者為第一順序繼承人？","options":{"A":"兄弟姊妹","B":"祖父母","C":"直系血親卑親屬","D":"父母"},"answer":"C","core":"繼承・法定繼承","explanation":"配偶另有繼承地位；其他法定繼承人的順序依民法第1138條判斷。","basis":"民法 §1138","status":"USER_CONFIRMED","source":"民法_40題_2026-10-14.md 第 19 題"},{"id":"CIV40_20","course":"family_law","term":"Y2S2","scopeWeek":13,"type":"mc","q":"被繼承人死亡，留下配偶及兩名子女，沒有其他應影響應繼分的特殊情形。配偶的法定應繼分為何？","options":{"A":"二分之一","B":"三分之一","C":"四分之一","D":"全部遺產"},"answer":"B","core":"繼承・配偶應繼分","explanation":"配偶與第一順序繼承人共同繼承時，按人數平均分配，因此三人各三分之一。","basis":"民法 §1144 ①","status":"USER_CONFIRMED","source":"民法_40題_2026-10-14.md 第 20 題"},{"id":"CIV40_21","course":"civ_general","term":"Y1S1","scopeWeek":14,"type":"mc","q":"甲與乙通謀，假裝將甲所有的房屋出售給乙，實際上雙方均無買賣真意。依民法第87條第1項，該買賣意思表示原則上如何？","options":{"A":"當然有效","B":"無效","C":"效力未定","D":"須經法院撤銷始失效"},"answer":"B","core":"民法總則・通謀虛偽意思表示","explanation":"","basis":"民法 §87 I","status":"USER_CONFIRMED","source":"民法_40題_2026-10-14.md 第 21 題"},{"id":"CIV40_22","course":"civ_general","term":"Y1S1","scopeWeek":14,"type":"mc","q":"依民法第88條，表意人因符合該條規定的重大錯誤而為意思表示，且其錯誤非由自己過失所致時，原則上得主張何種法律效果？","options":{"A":"撤銷意思表示","B":"意思表示當然無效","C":"對方當然負刑事責任","D":"契約自動轉換為贈與"},"answer":"A","core":"民法總則・重大錯誤","explanation":"","basis":"民法 §88 I","status":"USER_CONFIRMED","source":"民法_40題_2026-10-14.md 第 22 題"},{"id":"CIV40_23","course":"civ_general","term":"Y1S1","scopeWeek":11,"type":"mc","q":"甲與乙約定：「如果乙通過律師考試，甲就贈與乙一輛汽車。」此約定所附的條件屬於何者？","options":{"A":"解除條件","B":"停止條件","C":"不確定期限","D":"法定期間"},"answer":"B","core":"民法總則・條件","explanation":"","basis":"民法 §99","status":"USER_CONFIRMED","source":"民法_40題_2026-10-14.md 第 23 題"},{"id":"CIV40_24","course":"civ_general","term":"Y1S1","scopeWeek":16,"type":"mc","q":"依民法第148條第1項，權利的行使不得違反何種要求？","options":{"A":"必須使權利人獲得最大經濟利益","B":"不得以損害他人為主要目的","C":"必須事先取得法院同意","D":"不得對任何人造成不利益"},"answer":"B","core":"民法總則・權利濫用禁止","explanation":"","basis":"民法 §148 I","status":"USER_CONFIRMED","source":"民法_40題_2026-10-14.md 第 24 題"},{"id":"CIV40_25","course":"oblig_gen2","term":"Y2S1","scopeWeek":2,"type":"mc","q":"甲與乙訂立買賣契約後，因可歸責於甲的事由，致甲應交付的特定物滅失而不能給付。依民法第226條第1項，乙原則上得請求何者？","options":{"A":"損害賠償","B":"撤銷乙自己的所有法律行為","C":"直接取得甲的全部財產","D":"宣告甲喪失行為能力"},"answer":"A","core":"債法總論・給付不能","explanation":"","basis":"民法 §226 I","status":"USER_CONFIRMED","source":"民法_40題_2026-10-14.md 第 25 題"},{"id":"CIV40_26","course":"oblig_gen2","term":"Y2S1","scopeWeek":3,"type":"mc","q":"甲負有於10月1日交付特定設備的義務，履行期限已屆至，甲仍未交付，且不存在免責事由。下列何者最符合其債務不履行類型？","options":{"A":"給付不能","B":"給付遲延","C":"無因管理","D":"債權混同"},"answer":"B","core":"債法總論・給付遲延","explanation":"","basis":"民法 §229 I","status":"USER_CONFIRMED","source":"民法_40題_2026-10-14.md 第 26 題"},{"id":"CIV40_27","course":"oblig_gen2","term":"Y2S1","scopeWeek":16,"type":"mc","q":"依民法第242條，債務人怠於行使其權利時，債權人為保全債權，原則上得以自己名義行使何種權利？","options":{"A":"債務人一身專屬的權利","B":"債務人的權利，但專屬於債務人本身者除外","C":"所有第三人的權利","D":"行政機關的公權力"},"answer":"B","core":"債法總論・債權人代位權","explanation":"","basis":"民法 §242","status":"USER_CONFIRMED","source":"民法_40題_2026-10-14.md 第 27 題"},{"id":"CIV40_28","course":"oblig_gen2","term":"Y2S1","scopeWeek":16,"type":"mc","q":"甲為逃避債權人乙的追償，將其主要財產無償贈與丙，致乙的債權受到損害。乙原則上得考慮依民法第244條行使何種權利？","options":{"A":"債權人撤銷權","B":"所有物返還請求權","C":"夫妻剩餘財產分配請求權","D":"繼承回復請求權"},"answer":"A","core":"債法總論・詐害債權","explanation":"","basis":"民法 §244 I","status":"USER_CONFIRMED","source":"民法_40題_2026-10-14.md 第 28 題"},{"id":"CIV40_29","course":"oblig_gen2","term":"Y2S1","scopeWeek":12,"type":"mc","q":"依民法第273條第1項，連帶債務的債權人得如何請求給付？","options":{"A":"僅能向各債務人請求平均分攤的部分","B":"得向債務人中之一人、數人或全體，同時或先後請求全部或一部給付","C":"必須先向法院聲請分割債務","D":"只能向財產最多的債務人請求"},"answer":"B","core":"債法總論・連帶債務","explanation":"","basis":"民法 §273 I","status":"USER_CONFIRMED","source":"民法_40題_2026-10-14.md 第 29 題"},{"id":"CIV40_30","course":"oblig_spec","term":"Y2S2","scopeWeek":3,"type":"mc","q":"依民法第354條第1項，物之出賣人原則上應擔保買賣標的物在何時不存在法定瑕疵？","options":{"A":"買賣契約洽談開始時","B":"危險移轉於買受人時","C":"買受人第一次使用後一年","D":"出賣人取得所有權之前"},"answer":"B","core":"債法各論・買賣瑕疵擔保","explanation":"","basis":"民法 §354 I","status":"USER_CONFIRMED","source":"民法_40題_2026-10-14.md 第 30 題"},{"id":"CIV40_31","course":"oblig_spec","term":"Y2S2","scopeWeek":10,"type":"mc","q":"依民法第549條第1項，關於委任契約的終止，下列何者正確？","options":{"A":"委任人與受任人均不得終止","B":"只有委任人得隨時終止","C":"當事人任何一方得隨時終止","D":"僅得於委任事務完成後終止"},"answer":"C","core":"債法各論・委任契約","explanation":"","basis":"民法 §549 I","status":"USER_CONFIRMED","source":"民法_40題_2026-10-14.md 第 31 題"},{"id":"CIV40_32","course":"oblig_spec","term":"Y2S2","scopeWeek":13,"type":"mc","q":"依民法第745條，保證人於債權人未就主債務人的財產強制執行而無效果前，原則上得拒絕清償。此項權利稱為何者？","options":{"A":"同時履行抗辯權","B":"先訴抗辯權","C":"不安抗辯權","D":"時效取得抗辯權"},"answer":"B","core":"債法各論・保證契約","explanation":"","basis":"民法 §745","status":"USER_CONFIRMED","source":"民法_40題_2026-10-14.md 第 32 題"},{"id":"CIV40_33","course":"property","term":"Y2S1","scopeWeek":3,"type":"mc","q":"依民法第758條第1項，依法律行為而取得、設定、喪失或變更不動產物權者，非經何種程序，不生效力？","options":{"A":"交付","B":"登記","C":"公證","D":"鄰人同意"},"answer":"B","core":"物權・不動產物權變動","explanation":"","basis":"民法 §758 I","status":"USER_CONFIRMED","source":"民法_40題_2026-10-14.md 第 33 題"},{"id":"CIV40_34","course":"property","term":"Y2S1","scopeWeek":12,"type":"mc","q":"依民法第860條，普通抵押權的主要功能為何？","options":{"A":"使抵押權人立即取得抵押物所有權","B":"使債權人得就債務人或第三人提供的不動產，不移轉占有而就其賣得價金優先受償","C":"使抵押權人當然取得抵押物使用權","D":"使所有其他債權全部消滅"},"answer":"B","core":"物權・抵押權","explanation":"","basis":"民法 §860","status":"USER_CONFIRMED","source":"民法_40題_2026-10-14.md 第 34 題"},{"id":"CIV40_35","course":"property","term":"Y2S1","scopeWeek":14,"type":"mc","q":"依民法第769條，以所有的意思，20年間和平、公然、繼續占有他人未登記的不動產者，原則上得請求何種法律效果？","options":{"A":"直接取得所有權，無須任何程序","B":"登記為所有人","C":"取得永久租賃權","D":"取得法定抵押權"},"answer":"B","core":"物權・取得時效","explanation":"","basis":"民法 §769","status":"USER_CONFIRMED","source":"民法_40題_2026-10-14.md 第 35 題"},{"id":"CIV40_36","course":"property","term":"Y2S1","scopeWeek":11,"type":"mc","q":"依民法第832條，普通地上權主要是指以何種目的而使用他人土地的權利？","options":{"A":"在他人土地上下有建築物或其他工作物","B":"在他人土地上無償收取一切孳息","C":"永久禁止土地所有人使用土地","D":"取得他人土地的所有權"},"answer":"A","core":"物權・地上權","explanation":"","basis":"民法 §832","status":"USER_CONFIRMED","source":"民法_40題_2026-10-14.md 第 36 題"},{"id":"CIV40_37","course":"family_law","term":"Y2S2","scopeWeek":4,"type":"mc","q":"依現行民法第982條，結婚除應有書面及二人以上證人簽名外，尚須符合何種要件？","options":{"A":"舉行公開婚宴","B":"經法院判決","C":"由雙方當事人向戶政機關為結婚登記","D":"由雙方父母簽名同意"},"answer":"C","core":"親屬・婚姻的形式要件","explanation":"","basis":"民法 §982","status":"USER_CONFIRMED","source":"民法_40題_2026-10-14.md 第 37 題"},{"id":"CIV40_38","course":"family_law","term":"Y2S2","scopeWeek":11,"type":"mc","q":"依民法第1089條第1項，對於未成年子女權利義務的行使或負擔，原則上應如何處理？","options":{"A":"專由父親行使或負擔","B":"專由母親行使或負擔","C":"由父母共同行使或負擔","D":"一律由法院直接行使"},"answer":"C","core":"親屬・未成年子女權利義務","explanation":"","basis":"民法 §1089 I","status":"USER_CONFIRMED","source":"民法_40題_2026-10-14.md 第 38 題"},{"id":"CIV40_39","course":"family_law","term":"Y2S2","scopeWeek":15,"type":"mc","q":"依民法第1148條第2項，繼承人對於被繼承人的債務，原則上以何者為限負清償責任？","options":{"A":"繼承人自己的全部財產","B":"因繼承所得的遺產","C":"被繼承人生前全部收入","D":"繼承人配偶的財產"},"answer":"B","core":"繼承・限定責任","explanation":"","basis":"民法 §1148 II","status":"USER_CONFIRMED","source":"民法_40題_2026-10-14.md 第 39 題"},{"id":"CIV40_40","course":"family_law","term":"Y2S2","scopeWeek":14,"type":"mc","q":"依民法第1223條，直系血親卑親屬的特留分為其應繼分的多少？","options":{"A":"三分之一","B":"二分之一","C":"三分之二","D":"全部"},"answer":"B","core":"繼承・特留分","explanation":"","basis":"民法 §1223 ②","status":"USER_CONFIRMED","source":"民法_40題_2026-10-14.md 第 40 題"},{"id":"CIVS_01","course":"civ_general","term":"Y1S1","scopeWeek":5,"type":"mc","q":"依民法規定，下列何者為完全行為能力人？","options":{"A":"滿十五歲之未成年人","B":"滿十八歲之成年人","C":"所有已滿七歲之未成年人","D":"所有受輔助宣告之人均無行為能力"},"answer":"B","core":"行為能力","explanation":"","basis":"民法 §12、§13","status":"USER_CONFIRMED","source":"民法_六門課程補充40題_2026-10-14.md 第 1 題"},{"id":"CIVS_02","course":"civ_general","term":"Y1S1","scopeWeek":5,"type":"mc","q":"十六歲的甲未經法定代理人允許，購買價值十萬元的機車，且不屬於日常生活所必需。關於該買賣契約，下列何者正確？","options":{"A":"當然有效","B":"當然無效","C":"原則上須經法定代理人承認，始生效力","D":"甲須負刑事責任，契約始生效力"},"answer":"C","core":"限制行為能力人","explanation":"","basis":"民法 §79","status":"USER_CONFIRMED","source":"民法_六門課程補充40題_2026-10-14.md 第 2 題"},{"id":"CIVS_03","course":"civ_general","term":"Y1S1","scopeWeek":13,"type":"mc","q":"甲以書面向乙為解除契約的意思表示。依民法第95條第1項，非對話意思表示原則上於何時發生效力？","options":{"A":"意思表示到達相對人時","B":"甲寫完信件時","C":"甲產生解除意思時","D":"乙實際閱讀並同意時"},"answer":"A","core":"意思表示到達","explanation":"","basis":"民法 §95 I","status":"USER_CONFIRMED","source":"民法_六門課程補充40題_2026-10-14.md 第 3 題"},{"id":"CIVS_04","course":"civ_general","term":"Y1S1","scopeWeek":15,"type":"mc","q":"依民法第167條，代理權的授與，下列何者正確？","options":{"A":"一律須經法院許可","B":"一律須以公證書為之","C":"僅得向第三人為之","D":"得向代理人或代理人對之為代理行為的第三人，以意思表示為之"},"answer":"D","core":"代理權授與","explanation":"","basis":"民法 §167","status":"USER_CONFIRMED","source":"民法_六門課程補充40題_2026-10-14.md 第 4 題"},{"id":"CIVS_05","course":"civ_general","term":"Y1S1","scopeWeek":11,"type":"mc","q":"甲承諾乙：「如果乙通過考試，就給乙獎金。」甲為避免支付獎金，以不正當行為阻止條件成就。依民法第101條第1項，下列何者正確？","options":{"A":"條件永久不可能成就","B":"視為條件已成就","C":"約定當然無效","D":"乙只能請求精神慰撫金"},"answer":"B","core":"條件成就的妨害","explanation":"","basis":"民法 §101 I","status":"USER_CONFIRMED","source":"民法_六門課程補充40題_2026-10-14.md 第 5 題"},{"id":"CIVS_06","course":"civ_general","term":"Y1S1","scopeWeek":16,"type":"mc","q":"依民法第129條，下列何者原則上屬於消滅時效中斷事由？","options":{"A":"債權人單純忘記請求","B":"債務人搬家","C":"債權人依法起訴請求","D":"債權人與第三人討論債務"},"answer":"C","core":"消滅時效的中斷","explanation":"","basis":"民法 §129","status":"USER_CONFIRMED","source":"民法_六門課程補充40題_2026-10-14.md 第 6 題"},{"id":"CIVS_07","course":"civ_general","term":"Y1S1","scopeWeek":12,"type":"mc","q":"依民法第71條，法律行為違反強制或禁止規定時，原則上其效力如何？","options":{"A":"無效，但法律另有規定者不在此限","B":"一律有效","C":"僅得由行政機關撤銷","D":"須經雙方當事人同意始無效"},"answer":"A","core":"法律行為的無效","explanation":"","basis":"民法 §71","status":"USER_CONFIRMED","source":"民法_六門課程補充40題_2026-10-14.md 第 7 題"},{"id":"CIVS_08","course":"oblig_gen1","term":"Y1S2","scopeWeek":2,"type":"mc","q":"甲向乙表示願以十萬元出售自己的電腦，乙對價格及標的物完全同意。依民法第153條，原則上發生何種效果？","options":{"A":"必須經法院公證始成立","B":"必須實際交付電腦始成立買賣契約","C":"必須先支付價金始成立契約","D":"雙方意思表示一致，契約即成立"},"answer":"D","core":"契約成立","explanation":"","basis":"民法 §153 I","status":"USER_CONFIRMED","source":"民法_六門課程補充40題_2026-10-14.md 第 8 題"},{"id":"CIVS_09","course":"oblig_gen1","term":"Y1S2","scopeWeek":5,"type":"mc","q":"甲公開表示：「找到我遺失的狗並送回者，給付一萬元。」乙依廣告完成指定行為。依民法第164條，原則上甲應如何？","options":{"A":"得任意拒絕給付","B":"對完成指定行為之人負給付報酬義務","C":"只有乙事先書面承諾才須給付","D":"僅須支付乙的交通費"},"answer":"B","core":"懸賞廣告","explanation":"","basis":"民法 §164 I","status":"USER_CONFIRMED","source":"民法_六門課程補充40題_2026-10-14.md 第 9 題"},{"id":"CIVS_10","course":"oblig_gen1","term":"Y1S2","scopeWeek":14,"type":"mc","q":"依民法第184條第1項前段，一般侵權行為的成立要件包括下列何者？","options":{"A":"行為人須與被害人具有契約關係","B":"行為人須具有犯罪前科","C":"故意或過失不法侵害他人權利","D":"被害人須先向主管機關申訴"},"answer":"C","core":"侵權行為","explanation":"","basis":"民法 §184 I","status":"USER_CONFIRMED","source":"民法_六門課程補充40題_2026-10-14.md 第 10 題"},{"id":"CIVS_11","course":"oblig_gen1","term":"Y1S2","scopeWeek":15,"type":"mc","q":"甲為乙公司的受僱人，執行職務時因過失不法侵害丙的權利。依民法第188條第1項，下列何者正確？","options":{"A":"僱用人原則上與行為人連帶負損害賠償責任，但法律設有免責規定","B":"僱用人永遠不負責任","C":"僅由公司股東負責","D":"丙不得請求任何損害賠償"},"answer":"A","core":"僱用人責任","explanation":"","basis":"民法 §188 I","status":"USER_CONFIRMED","source":"民法_六門課程補充40題_2026-10-14.md 第 11 題"},{"id":"CIVS_12","course":"oblig_gen1","term":"Y1S2","scopeWeek":10,"type":"mc","q":"甲未受乙委任，也沒有法律上的義務，為避免乙的房屋漏水造成重大損害，主動進行必要修繕。此行為可能構成何種法律關係？","options":{"A":"消費借貸","B":"買賣","C":"保證","D":"無因管理"},"answer":"D","core":"無因管理","explanation":"","basis":"民法 §172","status":"USER_CONFIRMED","source":"民法_六門課程補充40題_2026-10-14.md 第 12 題"},{"id":"CIVS_13","course":"oblig_gen1","term":"Y1S2","scopeWeek":12,"type":"mc","q":"依民法第179條，不當得利返還請求權的基本要件包括何者？","options":{"A":"雙方必須具有書面契約","B":"無法律上原因受利益，致他人受損害","C":"受益人必須具有詐欺故意","D":"受益人必須受到刑事有罪判決"},"answer":"B","core":"不當得利","explanation":"","basis":"民法 §179","status":"USER_CONFIRMED","source":"民法_六門課程補充40題_2026-10-14.md 第 13 題"},{"id":"CIVS_14","course":"oblig_gen1","term":"Y1S2","scopeWeek":16,"type":"mc","q":"依民法第249條，契約因可歸責於付定金當事人的事由致不能履行時，除另有訂定外，定金應如何處理？","options":{"A":"加倍返還","B":"全數返還","C":"不得請求返還","D":"自動轉為違約金以外的精神慰撫金"},"answer":"C","core":"定金","explanation":"","basis":"民法 §249 ②","status":"USER_CONFIRMED","source":"民法_六門課程補充40題_2026-10-14.md 第 14 題"},{"id":"CIVS_15","course":"oblig_gen2","term":"Y2S1","scopeWeek":3,"type":"mc","q":"給付有確定期限者，依民法第229條第1項，債務人原則上自何時起負遲延責任？","options":{"A":"期限屆滿時","B":"債權人提起訴訟後一年","C":"法院判決確定時","D":"債權人第一次催告後六個月"},"answer":"A","core":"給付遲延","explanation":"","basis":"民法 §229 I","status":"USER_CONFIRMED","source":"民法_六門課程補充40題_2026-10-14.md 第 15 題"},{"id":"CIVS_16","course":"oblig_gen2","term":"Y2S1","scopeWeek":3,"type":"mc","q":"依民法第231條第2項，債務人遲延中，因不可抗力而生損害時，原則上應如何？","options":{"A":"債務人一律免責","B":"債權人一律自行負擔","C":"由法院任意分配","D":"債務人仍應負責，但能證明縱不遲延仍不免發生損害者，不在此限"},"answer":"D","core":"遲延中的不可抗力","explanation":"","basis":"民法 §231 II","status":"USER_CONFIRMED","source":"民法_六門課程補充40題_2026-10-14.md 第 16 題"},{"id":"CIVS_17","course":"oblig_gen2","term":"Y2S1","scopeWeek":5,"type":"mc","q":"依民法第227條，因可歸責於債務人的事由，致為不完全給付者，債權人得依其情形行使何種權利？","options":{"A":"一律直接取得債務人全部財產","B":"依給付遲延或給付不能的規定行使權利","C":"一律請求三倍懲罰性賠償","D":"自動取得債務人的繼承權"},"answer":"B","core":"不完全給付","explanation":"","basis":"民法 §227 I","status":"USER_CONFIRMED","source":"民法_六門課程補充40題_2026-10-14.md 第 17 題"},{"id":"CIVS_18","course":"oblig_gen2","term":"Y2S1","scopeWeek":11,"type":"mc","q":"甲與乙訂立買賣契約，甲應交付貨物，乙應支付價金，雙方均無先為給付義務。依民法第264條，甲原則上得如何？","options":{"A":"永久拒絕交付貨物","B":"直接解除所有其他契約","C":"於乙未為對待給付前，拒絕自己的給付","D":"要求乙先支付雙倍價金"},"answer":"C","core":"同時履行抗辯權","explanation":"","basis":"民法 §264 I","status":"USER_CONFIRMED","source":"民法_六門課程補充40題_2026-10-14.md 第 18 題"},{"id":"CIVS_19","course":"oblig_gen2","term":"Y2S1","scopeWeek":13,"type":"mc","q":"依民法第297條第1項，債權讓與未經讓與人或受讓人通知債務人時，原則上對債務人有何效果？","options":{"A":"對債務人不生效力","B":"債權讓與當然無效","C":"債務人因此免除全部債務","D":"債務人自動成為債權人"},"answer":"A","core":"債權讓與","explanation":"","basis":"民法 §297 I","status":"USER_CONFIRMED","source":"民法_六門課程補充40題_2026-10-14.md 第 19 題"},{"id":"CIVS_20","course":"oblig_gen2","term":"Y2S1","scopeWeek":13,"type":"mc","q":"甲積欠乙十萬元，丙與乙訂立契約，約定由丙承擔甲的債務。依民法第300條，下列何者正確？","options":{"A":"必須經甲書面同意始成立","B":"只能由法院命令成立","C":"丙只能成為保證人","D":"第三人得與債權人訂立契約承擔債務"},"answer":"D","core":"債務承擔","explanation":"","basis":"民法 §300","status":"USER_CONFIRMED","source":"民法_六門課程補充40題_2026-10-14.md 第 20 題"},{"id":"CIVS_21","course":"oblig_gen2","term":"Y2S1","scopeWeek":14,"type":"mc","q":"依民法第334條第1項，二人互負債務，給付種類相同，且均屆清償期者，原則上得如何？","options":{"A":"當然使兩個契約全部無效","B":"各以其債務與他方債務互為抵銷","C":"僅得聲請刑事法院處理","D":"必須先經公證始得抵銷"},"answer":"B","core":"抵銷","explanation":"","basis":"民法 §334 I","status":"USER_CONFIRMED","source":"民法_六門課程補充40題_2026-10-14.md 第 21 題"},{"id":"CIVS_22","course":"oblig_gen2","term":"Y2S1","scopeWeek":14,"type":"mc","q":"依民法第343條，債權人向債務人表示免除債務的意思時，原則上發生何種效果？","options":{"A":"債務轉由國家承擔","B":"債務自動加倍","C":"債之關係消滅","D":"債權轉讓給第三人"},"answer":"C","core":"債務免除","explanation":"","basis":"民法 §343","status":"USER_CONFIRMED","source":"民法_六門課程補充40題_2026-10-14.md 第 22 題"},{"id":"CIVS_23","course":"oblig_spec","term":"Y2S2","scopeWeek":3,"type":"mc","q":"依民法第345條，買賣契約的基本內容為何？","options":{"A":"一方移轉財產權於他方，他方支付價金","B":"一方無償提供勞務，他方表示感謝","C":"一方提供擔保，他方不負任何義務","D":"一方交付財產，他方必須返還同一物"},"answer":"A","core":"買賣契約","explanation":"","basis":"民法 §345 I","status":"USER_CONFIRMED","source":"民法_六門課程補充40題_2026-10-14.md 第 23 題"},{"id":"CIVS_24","course":"oblig_spec","term":"Y2S2","scopeWeek":3,"type":"mc","q":"依民法第359條，買賣標的物具有出賣人應負擔保責任的瑕疵時，買受人原則上得主張何種權利？","options":{"A":"一律請求三倍價金","B":"直接取得出賣人其他財產","C":"請求法院宣告出賣人破產","D":"解除契約或請求減少價金，但解除契約顯失公平者僅得請求減少價金"},"answer":"D","core":"物之瑕疵擔保","explanation":"","basis":"民法 §359","status":"USER_CONFIRMED","source":"民法_六門課程補充40題_2026-10-14.md 第 24 題"},{"id":"CIVS_25","course":"oblig_spec","term":"Y2S2","scopeWeek":4,"type":"mc","q":"依民法第421條，租賃契約的基本內容為何？","options":{"A":"一方移轉所有權，他方支付價金","B":"一方以物租與他方使用、收益，他方支付租金","C":"一方為他方完成工作，他方支付報酬","D":"一方無償交付金錢，他方返還同額金錢"},"answer":"B","core":"租賃契約","explanation":"","basis":"民法 §421 I","status":"USER_CONFIRMED","source":"民法_六門課程補充40題_2026-10-14.md 第 25 題"},{"id":"CIVS_26","course":"oblig_spec","term":"Y2S2","scopeWeek":15,"type":"mc","q":"依民法第490條，承攬契約的基本特徵為何？","options":{"A":"承攬人必須永久受定作人指揮監督","B":"承攬人只要提供勞務時間，即當然取得全部報酬","C":"承攬人約定完成一定工作，定作人俟工作完成給付報酬","D":"承攬人必須將自己的財產無償贈與定作人"},"answer":"C","core":"承攬契約","explanation":"","basis":"民法 §490 I","status":"USER_CONFIRMED","source":"民法_六門課程補充40題_2026-10-14.md 第 26 題"},{"id":"CIVS_27","course":"oblig_spec","term":"Y2S2","scopeWeek":10,"type":"mc","q":"依民法第528條，委任契約的基本內容為何？","options":{"A":"一方委託他方處理事務，他方允為處理","B":"一方必須移轉土地所有權","C":"一方交付金錢，他方必須支付利息","D":"一方保證他人債務必定清償"},"answer":"A","core":"委任契約","explanation":"","basis":"民法 §528","status":"USER_CONFIRMED","source":"民法_六門課程補充40題_2026-10-14.md 第 27 題"},{"id":"CIVS_28","course":"oblig_spec","term":"Y2S2","scopeWeek":14,"type":"mc","q":"依民法第408條第1項，贈與物的權利尚未移轉前，贈與人原則上得如何？","options":{"A":"一律不得撤銷贈與","B":"必須經受贈人同意始得撤銷","C":"必須取得法院判決始得撤銷","D":"得撤銷贈與，但法律另有例外規定"},"answer":"D","core":"贈與撤銷","explanation":"","basis":"民法 §408 I","status":"USER_CONFIRMED","source":"民法_六門課程補充40題_2026-10-14.md 第 28 題"},{"id":"CIVS_29","course":"oblig_spec","term":"Y2S2","scopeWeek":16,"type":"mc","q":"依民法第589條，寄託契約的基本內容為何？","options":{"A":"一方移轉所有權，他方支付價金","B":"一方以物交付他方保管，他方允為保管","C":"一方為他方完成一定工作","D":"一方承擔他人的債務"},"answer":"B","core":"寄託契約","explanation":"","basis":"民法 §589 I","status":"USER_CONFIRMED","source":"民法_六門課程補充40題_2026-10-14.md 第 29 題"},{"id":"CIVS_30","course":"property","term":"Y2S1","scopeWeek":2,"type":"mc","q":"依民法第757條，物權除依法律或習慣外，原則上不得如何？","options":{"A":"移轉","B":"登記","C":"創設","D":"繼承"},"answer":"C","core":"物權法定原則","explanation":"","basis":"民法 §757","status":"USER_CONFIRMED","source":"民法_六門課程補充40題_2026-10-14.md 第 30 題"},{"id":"CIVS_31","course":"property","term":"Y2S1","scopeWeek":4,"type":"mc","q":"依民法第761條第1項，動產物權的讓與，原則上非將動產如何，不生效力？","options":{"A":"交付","B":"公證","C":"登記於土地登記簿","D":"經法院判決"},"answer":"A","core":"動產所有權移轉","explanation":"","basis":"民法 §761 I","status":"USER_CONFIRMED","source":"民法_六門課程補充40題_2026-10-14.md 第 31 題"},{"id":"CIVS_32","course":"property","term":"Y2S1","scopeWeek":7,"type":"mc","q":"依民法第823條第1項，各共有人原則上得如何？","options":{"A":"永久禁止其他共有人使用共有物","B":"單獨出售整個共有物而不受限制","C":"無條件取得其他共有人的應有部分","D":"隨時請求分割共有物，但法律另有規定或因物的使用目的不能分割者除外"},"answer":"D","core":"共有物分割","explanation":"","basis":"民法 §823 I","status":"USER_CONFIRMED","source":"民法_六門課程補充40題_2026-10-14.md 第 32 題"},{"id":"CIVS_33","course":"property","term":"Y2S1","scopeWeek":11,"type":"mc","q":"依民法第832條，普通地上權的主要內容為何？","options":{"A":"對他人土地享有永久所有權","B":"以在他人土地上下有建築物或其他工作物為目的而使用其土地","C":"對他人土地享有任意出售權","D":"對他人土地上的所有動產享有抵押權"},"answer":"B","core":"普通地上權","explanation":"","basis":"民法 §832","status":"USER_CONFIRMED","source":"民法_六門課程補充40題_2026-10-14.md 第 33 題"},{"id":"CIVS_34","course":"property","term":"Y2S1","scopeWeek":12,"type":"mc","q":"依民法第860條，普通抵押權的特徵為何？","options":{"A":"必須將抵押物交付抵押權人占有","B":"抵押權人當然取得抵押物所有權","C":"不移轉占有，以不動產供債權擔保並得就賣得價金優先受償","D":"抵押權人得無條件使用抵押物"},"answer":"C","core":"普通抵押權","explanation":"","basis":"民法 §860","status":"USER_CONFIRMED","source":"民法_六門課程補充40題_2026-10-14.md 第 34 題"},{"id":"CIVS_35","course":"property","term":"Y2S1","scopeWeek":13,"type":"mc","q":"依民法第884條，動產質權的基本特徵為何？","options":{"A":"債權人占有債務人或第三人移交的動產，以擔保債權","B":"債權人必須取得土地所有權","C":"質權人不須占有質物，且一律不得交付","D":"質權僅能設定於不動產"},"answer":"A","core":"質權","explanation":"","basis":"民法 §884","status":"USER_CONFIRMED","source":"民法_六門課程補充40題_2026-10-14.md 第 35 題"},{"id":"CIVS_36","course":"family_law","term":"Y2S2","scopeWeek":2,"type":"mc","q":"依民法第968條，甲與其親生兄弟乙之間，屬於幾親等的旁系血親？","options":{"A":"一親等","B":"三親等","C":"四親等","D":"二親等"},"answer":"D","core":"親等計算","explanation":"","basis":"民法 §968","status":"USER_CONFIRMED","source":"民法_六門課程補充40題_2026-10-14.md 第 36 題"},{"id":"CIVS_37","course":"family_law","term":"Y2S2","scopeWeek":4,"type":"mc","q":"依民法第982條，結婚應具備下列何種形式要件？","options":{"A":"僅須雙方口頭同意","B":"書面、有二人以上證人簽名，並由雙方當事人向戶政機關為結婚登記","C":"必須先舉行婚宴","D":"必須經法院判決許可"},"answer":"B","core":"婚姻成立","explanation":"","basis":"民法 §982","status":"USER_CONFIRMED","source":"民法_六門課程補充40題_2026-10-14.md 第 37 題"},{"id":"CIVS_38","course":"family_law","term":"Y2S2","scopeWeek":6,"type":"mc","q":"依民法第1050條，夫妻兩願離婚原則上應如何辦理？","options":{"A":"僅須一方寄發存證信函","B":"僅須分居滿一年","C":"以書面為之，有二人以上證人簽名，並向戶政機關為離婚登記","D":"必須經法院判決始得離婚"},"answer":"C","core":"兩願離婚","explanation":"","basis":"民法 §1050","status":"USER_CONFIRMED","source":"民法_六門課程補充40題_2026-10-14.md 第 38 題"},{"id":"CIVS_39","course":"family_law","term":"Y2S2","scopeWeek":13,"type":"mc","q":"依民法第1147條，繼承因何種事實而開始？","options":{"A":"被繼承人死亡","B":"被繼承人退休","C":"被繼承人訂立遺囑","D":"被繼承人出售不動產"},"answer":"A","core":"繼承開始","explanation":"","basis":"民法 §1147","status":"USER_CONFIRMED","source":"民法_六門課程補充40題_2026-10-14.md 第 39 題"},{"id":"CIVS_40","course":"family_law","term":"Y2S2","scopeWeek":15,"type":"mc","q":"依民法第1174條，繼承人拋棄繼承，原則上應於知悉其得繼承之時起多久內，以書面向法院為之？","options":{"A":"一個月","B":"六個月","C":"一年","D":"三個月"},"answer":"D","core":"拋棄繼承","explanation":"","basis":"民法 §1174 II","status":"USER_CONFIRMED","source":"民法_六門課程補充40題_2026-10-14.md 第 40 題"},{"id":"CRIM45_01","course":"crim_gen1","term":"Y1S1","scopeWeek":3,"type":"mc","q":"甲於行為時觸犯某罪，法定刑為一年以上五年以下有期徒刑。案件尚未判決確定前，法律修正為六月以上三年以下有期徒刑。依刑法第2條第1項，下列何者正確？","options":{"A":"一律適用行為時法律","B":"一律適用裁判時法律，不論是否有利","C":"原則適用行為時法律，但行為後法律有利於行為人者，適用最有利的法律","D":"由檢察官任意選擇適用法律"},"answer":"C","core":"法律變更與從舊從輕","explanation":"","basis":"刑法 §2 I","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 1 題"},{"id":"CRIM45_02","course":"crim_gen1","term":"Y1S1","scopeWeek":15,"type":"mc","q":"甲人在日本，透過網路對位於台灣的乙實施詐欺，乙在台灣陷於錯誤並交付財物。依刑法第4條，下列何者正確？","options":{"A":"犯罪行為或結果有一在我國領域內，即屬在我國領域內犯罪","B":"只有甲本人進入台灣，才可能適用我國刑法","C":"網路犯罪一律不適用屬地原則","D":"必須甲乙均具有我國國籍才可適用"},"answer":"A","core":"犯罪地的認定","explanation":"","basis":"刑法 §4","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 2 題"},{"id":"CRIM45_03","course":"crim_gen1","term":"Y1S1","scopeWeek":12,"type":"mc","q":"甲明知高速駕車衝入擁擠人群可能撞死人，仍為報復他人而加速衝撞，對於他人死亡的發生抱持無所謂的態度。依刑法第13條，下列何者最適當？","options":{"A":"必然僅成立無認識過失","B":"因甲未特別指定被害人，所以不可能成立故意","C":"只有實際撞死人後才可能認定主觀故意","D":"甲可能具有殺人的間接故意"},"answer":"D","core":"間接故意與有認識過失","explanation":"","basis":"刑法 §13 II","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 3 題"},{"id":"CRIM45_04","course":"crim_gen1","term":"Y1S1","scopeWeek":6,"type":"mc","q":"甲駕車不慎撞傷乙，使乙倒在偏僻道路旁。甲明知乙有生命危險且自己能立即救助，卻故意離去，最終乙因未獲救助而死亡。關於刑法第15條，下列何者正確？","options":{"A":"只有父母對子女才可能負保證人義務","B":"因自己先前行為造成危險者，可能負防止結果發生的義務","C":"不作為永遠不可能成立殺人罪","D":"只要沒有再次碰觸乙，就不可能負刑事責任"},"answer":"B","core":"不作為犯與保證人地位","explanation":"","basis":"刑法 §15","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 4 題"},{"id":"CRIM45_05","course":"crim_gen2","term":"Y1S2","scopeWeek":10,"type":"mc","q":"甲明知自己所做的事實內容，但誤認該行為不受法律禁止。依刑法第16條，下列何者正確？","options":{"A":"只要自稱不懂法律，一律無罪","B":"只要不知道法條編號，一律免責","C":"除有正當理由而無法避免外，不得因不知法律而免責，但得依情節減輕其刑","D":"禁止錯誤一律按故意犯罪加重其刑"},"answer":"C","core":"禁止錯誤","explanation":"","basis":"刑法 §16","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 5 題"},{"id":"CRIM45_06","course":"crim_gen2","term":"Y1S2","scopeWeek":7,"type":"mc","q":"甲於犯罪行為時，因精神障礙致完全不能辨識其行為違法，也欠缺依其辨識而行為的能力，且非故意或過失自行招致。依刑法第19條，下列何者正確？","options":{"A":"不罰","B":"一律處無期徒刑","C":"一律僅減輕其刑二分之一","D":"必須被害人同意才能免責"},"answer":"A","core":"責任能力","explanation":"","basis":"刑法 §19 I","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 6 題"},{"id":"CRIM45_07","course":"crim_gen2","term":"Y1S2","scopeWeek":3,"type":"mc","q":"甲持刀正在攻擊乙，乙為阻止攻擊，立即以必要的力量推開甲，使甲跌倒受傷。依刑法第23條，下列何者最適當？","options":{"A":"只要甲受傷，乙必然成立傷害罪","B":"只有警察才可以正當防衛","C":"正當防衛只能保護財產權","D":"乙可能成立正當防衛而不罰"},"answer":"D","core":"正當防衛","explanation":"","basis":"刑法 §23","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 7 題"},{"id":"CRIM45_08","course":"crim_gen2","term":"Y1S2","scopeWeek":4,"type":"mc","q":"甲遭遇突發山洪，為避免立即溺斃，在沒有其他可行避險方式的情況下，破壞無人小屋的門窗進入避難。依刑法第24條，下列何者最適當？","options":{"A":"只要毀損他人財產，一律不能主張緊急避難","B":"符合法定要件時，甲可能因緊急避難而不罰","C":"緊急避難只適用於保護國家法益","D":"緊急避難必須先取得屋主書面同意"},"answer":"B","core":"緊急避難","explanation":"","basis":"刑法 §24 I","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 8 題"},{"id":"CRIM45_09","course":"crim_gen2","term":"Y1S2","scopeWeek":12,"type":"mc","q":"甲誤將普通砂糖當作劇毒藥物，企圖以該砂糖毒殺乙。假設甲所採取的方式客觀上完全不可能致死，也不存在致死危險。依刑法第26條，下列何者正確？","options":{"A":"一律成立殺人既遂罪","B":"一律成立過失致死罪","C":"行為不能發生犯罪結果且無危險者，不罰","D":"必須依殺人既遂罪處罰"},"answer":"C","core":"不能犯","explanation":"","basis":"刑法 §26","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 9 題"},{"id":"CRIM45_10","course":"crim_gen2","term":"Y1S2","scopeWeek":12,"type":"mc","q":"甲持刀欲殺乙，已朝乙刺出一刀但未刺中。甲隨即出於自己意願放棄殺人，收刀離去，乙未受傷。假設已達殺人罪著手階段，依刑法第27條，下列何者正確？","options":{"A":"符合中止未遂要件時，減輕或免除其刑","B":"甲必然成立殺人既遂","C":"甲因未造成死亡，一律不成立任何犯罪","D":"中止未遂必須由警察制止才成立"},"answer":"A","core":"中止未遂","explanation":"","basis":"刑法 §27 I","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 10 題"},{"id":"CRIM45_11","course":"crim_gen2","term":"Y1S2","scopeWeek":13,"type":"mc","q":"甲乙事先約定共同搶劫商店，由甲持刀威嚇店員，乙負責拿取收銀機內現金。兩人依計畫完成犯罪。下列何者最適當？","options":{"A":"只有實際拿錢的乙可能成立正犯","B":"只有持刀的甲可能成立正犯","C":"兩人都只能成立幫助犯","D":"甲乙具有共同犯意聯絡及行為分擔，可能成立共同正犯"},"answer":"D","core":"共同正犯","explanation":"","basis":"刑法 §28","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 11 題"},{"id":"CRIM45_12","course":"crim_gen2","term":"Y1S2","scopeWeek":14,"type":"mc","q":"甲原本沒有殺害丙的意思，乙反覆勸說甲殺害丙，最終使甲產生殺人犯意並著手實行。依刑法第29條，下列何者正確？","options":{"A":"乙必然不成立犯罪","B":"乙可能成立殺人罪的教唆犯","C":"乙只有親自持刀才可能成立犯罪","D":"教唆犯一律按幫助犯處罰"},"answer":"B","core":"教唆犯","explanation":"","basis":"刑法 §29","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 12 題"},{"id":"CRIM45_13","course":"crim_gen2","term":"Y1S2","scopeWeek":14,"type":"mc","q":"甲明知乙計畫竊取他人財物，仍基於幫助竊盜的意思提供犯罪工具。乙不知道工具是甲為協助犯罪而特別準備，仍利用該工具完成竊盜。依刑法第30條，下列何者正確？","options":{"A":"乙不知道甲的幫助意思，甲必然無罪","B":"幫助犯必須親自實行竊盜構成要件","C":"即使正犯不知幫助之情，甲仍可能成立幫助犯","D":"幫助犯的刑罰必須重於正犯"},"answer":"C","core":"幫助犯","explanation":"","basis":"刑法 §30 I","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 13 題"},{"id":"CRIM45_14","course":"crim_gen2","term":"Y1S2","scopeWeek":14,"type":"mc","q":"甲為公務員，乙為一般民眾。兩人基於共同犯意，分工實行一項以公務員身分作為成立要件的犯罪。依刑法第31條第1項，下列何者正確？","options":{"A":"無特定身分的乙仍可能以正犯或共犯論，但得減輕其刑","B":"乙因不具公務員身分，一律無罪","C":"乙必須先取得公務員資格才可能成立共犯","D":"只有公務員才能教唆公務員犯罪"},"answer":"A","core":"身分犯","explanation":"","basis":"刑法 §31 I","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 14 題"},{"id":"CRIM45_15","course":"crim_gen2","term":"Y1S2","scopeWeek":15,"type":"mc","q":"甲以單一行為同時觸犯兩個不同罪名，且符合刑法第55條想像競合的要件。原則上應如何處斷？","options":{"A":"一律將兩罪刑期相加","B":"一律免除其中較重的罪","C":"由被告自由選擇適用哪一罪","D":"從一重處斷，並注意法律所定封鎖作用等限制"},"answer":"D","core":"想像競合","explanation":"","basis":"刑法 §55","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 15 題"},{"id":"CRIM45_16","course":"crim_spec","term":"Y2S1","scopeWeek":3,"type":"mc","q":"甲因與乙發生爭執，故意毆打乙，主觀上僅有傷害故意，沒有殺人故意。乙因傷勢死亡，且甲對死亡結果具有預見可能性。下列何者最適當？","options":{"A":"必然成立故意殺人罪","B":"可能成立傷害致死罪","C":"必然不成立任何犯罪","D":"僅能成立毀損罪"},"answer":"B","core":"殺人罪與傷害致死罪","explanation":"","basis":"刑法 §277 II","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 16 題"},{"id":"CRIM45_17","course":"crim_spec","term":"Y2S1","scopeWeek":2,"type":"mc","q":"甲基於殺人故意朝乙胸口開槍，乙中彈後經緊急手術獲救。假設甲已著手殺人，且不存在阻卻違法或責任事由，下列何者最適當？","options":{"A":"成立殺人既遂罪","B":"僅成立普通傷害罪","C":"成立殺人未遂罪","D":"因乙沒有死亡，甲不成立犯罪"},"answer":"C","core":"殺人未遂","explanation":"","basis":"刑法 §271 II","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 17 題"},{"id":"CRIM45_18","course":"crim_spec","term":"Y2S1","scopeWeek":3,"type":"mc","q":"甲故意攻擊乙的眼睛，造成乙一眼視能永久嚴重減損。依刑法第10條及第278條，下列何者最適當？","options":{"A":"可能成立重傷罪","B":"必然僅成立普通傷害罪","C":"只有雙眼完全失明才可能成立重傷","D":"只要乙仍能工作，就不可能成立重傷"},"answer":"A","core":"重傷害罪","explanation":"","basis":"刑法 §10 IV ①、§278","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 18 題"},{"id":"CRIM45_19","course":"crim_spec","term":"Y2S1","scopeWeek":2,"type":"mc","q":"甲駕車時疏於注意前方狀況，撞上依法行走於行人穿越道的乙，致乙死亡。假設甲具有注意義務、注意能力，且死亡結果可歸責於其過失。下列何者最適當？","options":{"A":"必然成立故意殺人罪","B":"必然成立強盜罪","C":"因沒有殺人故意，一律無罪","D":"可能成立過失致死罪"},"answer":"D","core":"過失致死罪","explanation":"","basis":"刑法 §276","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 19 題"},{"id":"CRIM45_20","course":"crim_spec","term":"Y2S1","scopeWeek":5,"type":"mc","q":"甲為逼乙還錢，將乙反鎖在房間內三小時，不允許乙離開。假設乙並未同意，甲也沒有法律上的正當理由。下列何者最適當？","options":{"A":"因甲是債權人，所以行為必然合法","B":"可能成立刑法第302條剝奪他人行動自由罪","C":"只有拘禁超過二十四小時才可能成立犯罪","D":"只有警察才能成立剝奪行動自由罪"},"answer":"B","core":"剝奪行動自由","explanation":"","basis":"刑法 §302","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 20 題"},{"id":"CRIM45_21","course":"crim_spec","term":"Y2S1","scopeWeek":5,"type":"mc","q":"甲以毆打相威脅，迫使乙簽署原本沒有義務簽署的文件。假設甲的行為已達強暴、脅迫程度，且無其他阻卻違法事由。下列何者最適當？","options":{"A":"只有文件經過公證才成立犯罪","B":"只有乙實際受傷才可能成立犯罪","C":"可能成立刑法第304條強制罪","D":"甲只要沒有取得財物就必然無罪"},"answer":"C","core":"強制罪","explanation":"","basis":"刑法 §304","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 21 題"},{"id":"CRIM45_22","course":"crim_spec","term":"Y2S1","scopeWeek":5,"type":"mc","q":"甲向乙傳訊：「明天我要放火燒掉你家。」依具體情況，該訊息已使乙的安全受到危害。依刑法第305條，下列何者最適當？","options":{"A":"可能成立恐嚇危害安全罪","B":"只有甲實際放火才可能成立恐嚇罪","C":"恐嚇罪必須以當面口頭表示為限","D":"只有威脅生命，威脅財產不受規範"},"answer":"A","core":"恐嚇危害安全","explanation":"","basis":"刑法 §305","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 22 題"},{"id":"CRIM45_23","course":"crim_spec","term":"Y2S1","scopeWeek":5,"type":"mc","q":"甲未經乙同意，且無正當理由，擅自進入乙的住宅。依刑法第306條，下列何者正確？","options":{"A":"只有甲偷走東西才可能成立犯罪","B":"只有在深夜侵入才可能成立犯罪","C":"住宅必須是乙所有才受保護","D":"甲可能成立無故侵入住宅罪"},"answer":"D","core":"侵入住宅","explanation":"","basis":"刑法 §306","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 23 題"},{"id":"CRIM45_24","course":"crim_spec","term":"Y2S1","scopeWeek":6,"type":"mc","q":"甲為損害乙的名譽，故意向多人散布自己捏造的「乙侵占公司公款」之具體事實。假設內容足以毀損乙的名譽，也無其他阻卻違法事由。下列何者最適當？","options":{"A":"只有乙實際失業才可能成立犯罪","B":"甲可能成立誹謗罪","C":"只要甲沒有使用髒話，就不可能成立犯罪","D":"只要以文字散布，就必然不受刑法規範"},"answer":"B","core":"誹謗罪","explanation":"","basis":"刑法 §310","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 24 題"},{"id":"CRIM45_25","course":"crim_spec","term":"Y2S1","scopeWeek":14,"type":"mc","q":"甲未經乙同意，冒用乙的名義製作一份借款契約，表示乙向甲借款十萬元，足以損害乙。依刑法第210條，下列何者最適當？","options":{"A":"因甲沒有使用公文書，所以必然無罪","B":"只有實際取得十萬元才可能成立犯罪","C":"可能成立偽造私文書罪","D":"只要文件未經公證，就不可能成立偽造文書罪"},"answer":"C","core":"偽造私文書","explanation":"","basis":"刑法 §210","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 25 題"},{"id":"CRIM45_26","course":"crim_spec","term":"Y2S1","scopeWeek":14,"type":"mc","q":"甲明知某項事項不實，仍向僅負形式審查義務的公務員提出虛偽申報，使公務員將該不實事項登載於職務上掌管的公文書，足以生損害於公眾或他人。下列何者最適當？","options":{"A":"可能成立刑法第214條使公務員登載不實罪","B":"因公務員親自登載，甲必然無罪","C":"只有甲親自修改公文書才可能成立犯罪","D":"只有公務員收受賄賂才可能成立犯罪"},"answer":"A","core":"使公務員登載不實","explanation":"","basis":"刑法 §214","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 26 題"},{"id":"CRIM45_27","course":"crim_spec","term":"Y2S1","scopeWeek":10,"type":"mc","q":"甲在便利商店內，意圖為自己不法所有，趁店員不注意，將架上商品藏入背包並攜離商店，未付款。下列何者最適當？","options":{"A":"甲可能成立侵占遺失物罪","B":"因商品價值不高，必然不成立犯罪","C":"甲必須以暴力取得商品才成立竊盜","D":"甲可能成立普通竊盜罪"},"answer":"D","core":"竊盜罪","explanation":"","basis":"刑法 §320","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 27 題"},{"id":"CRIM45_28","course":"crim_spec","term":"Y2S1","scopeWeek":12,"type":"mc","q":"甲受乙委託保管一台筆記型電腦，之後意圖為自己不法所有，將該電腦據為己有並拒絕返還。下列何者最適當？","options":{"A":"必然成立強盜罪","B":"可能成立侵占罪","C":"因電腦原本合法交付甲保管，所以永遠不成立犯罪","D":"必然成立詐欺取財罪"},"answer":"B","core":"侵占罪","explanation":"","basis":"刑法 §335","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 28 題"},{"id":"CRIM45_29","course":"crim_spec","term":"Y2S1","scopeWeek":13,"type":"mc","q":"甲明知自己沒有任何商品，仍在網路上刊登虛假的商品販售資訊，使乙陷於錯誤而匯款一萬元。甲取得款項後立即失聯。假設甲自始具有不法所有意圖。下列何者最適當？","options":{"A":"因甲沒有與乙見面，所以不可能成立詐欺","B":"只有金額超過十萬元才可能成立詐欺","C":"甲可能成立詐欺取財罪","D":"甲必然僅成立民事債務不履行"},"answer":"C","core":"詐欺取財罪","explanation":"","basis":"刑法 §339","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 29 題"},{"id":"CRIM45_30","course":"crim_spec","term":"Y2S1","scopeWeek":13,"type":"mc","q":"甲向乙表示：「如果不交給我五萬元，我就公布你不願讓人知道的私人照片。」乙因恐懼而交付款項。假設甲具有不法所有意圖，且未施用達到強盜罪程度的強暴、脅迫。下列何者最適當？","options":{"A":"甲可能成立恐嚇取財罪","B":"甲必然成立竊盜罪","C":"只要乙親自交付財物，甲就不可能成立犯罪","D":"只有威脅殺人才能成立恐嚇取財罪"},"answer":"A","core":"恐嚇取財罪","explanation":"","basis":"刑法 §346","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 30 題"},{"id":"CRIM45_31","course":"crim_gen1","term":"Y1S1","scopeWeek":2,"type":"mc","q":"甲的行為在社會上受到強烈譴責，但行為時並無法律明文處罰該行為。依刑法第1條，下列何者正確？","options":{"A":"法院得直接依社會輿論判處甲有罪","B":"法院得類推適用最相近的刑罰規定處罰甲","C":"只要行為不道德，即可成立犯罪","D":"原則上不得在欠缺行為時法律明文處罰規定的情況下，對甲科處刑罰"},"answer":"D","core":"罪刑法定原則","explanation":"","basis":"刑法 §1","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 31 題"},{"id":"CRIM45_32","course":"crim_gen2","term":"Y1S2","scopeWeek":7,"type":"mc","q":"甲長期患有嚴重精神疾病。某日，甲因精神症狀發作，完全無法辨識自己持刀攻擊乙的行為違法，也無法依其辨識控制行為。關於甲的刑事責任，下列何者最適當？","options":{"A":"只要甲客觀上造成乙受傷，就必然成立故意傷害罪","B":"甲因行為時欠缺辨識及控制能力，可能不具刑法上的責任能力","C":"精神疾病與刑事責任完全無關，法院不得調查","D":"甲只要事前曾經持刀，就必然具有完整責任能力"},"answer":"B","core":"刑法上的責任能力","explanation":"","basis":"刑法 §19 I","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 32 題"},{"id":"CRIM45_33","course":"crim_gen1","term":"Y1S1","scopeWeek":13,"type":"mc","q":"甲在餐廳離開時，誤將外觀完全相同的乙之雨傘當成自己的雨傘帶走。甲確實相信該傘為自己所有，並無其他不法意圖。下列何者最適當？","options":{"A":"甲必然成立故意竊盜罪","B":"甲必然成立強盜罪","C":"甲對財物屬於他人所有的事實認識有誤，可能欠缺竊盜故意","D":"只要乙沒有立即發現，甲即成立竊盜既遂罪"},"answer":"C","core":"構成要件錯誤","explanation":"","basis":"","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 33 題"},{"id":"CRIM45_34","course":"crim_gen1","term":"Y1S1","scopeWeek":7,"type":"mc","q":"甲違規超速駕駛，乙則在甲行經的道路旁突然遭雷擊死亡。經查乙的死亡與甲的駕駛行為毫無因果關係。下列何者正確？","options":{"A":"只要甲有違規行為，就必須對乙死亡負刑責","B":"甲的超速行為與乙死亡無因果關係，不能僅因甲違規即將死亡結果歸責於甲","C":"甲必然成立故意殺人罪","D":"只要甲與乙同時出現在現場，即可推定結果歸責"},"answer":"B","core":"客觀歸責・風險實現","explanation":"","basis":"","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 34 題"},{"id":"CRIM45_35","course":"crim_gen1","term":"Y1S1","scopeWeek":13,"type":"mc","q":"甲基於殺人故意將乙推入河中，原以為乙會溺斃；乙實際上因撞擊河中岩石而死亡。假設撞擊岩石屬於該推落行為所產生的通常風險，且因果歷程偏差並不重大。下列何者最適當？","options":{"A":"只要死亡方式與甲預想不同，就必然無罪","B":"甲只能成立過失致死罪","C":"甲必然僅成立殺人預備罪","D":"因果歷程的非重大偏差，原則上不妨礙殺人既遂的認定"},"answer":"D","core":"因果歷程錯誤","explanation":"","basis":"","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 35 題"},{"id":"CRIM45_36","course":"crim_gen2","term":"Y1S2","scopeWeek":5,"type":"mc","q":"甲在深夜見乙突然伸手進入外套，誤以為乙準備持刀攻擊自己，於是先將乙推倒。實際上乙只是準備拿手機，且客觀上並無現在不法侵害。關於甲的刑事責任，下列何者最適當？","options":{"A":"應區分客觀上是否存在正當防衛情狀，以及甲對該情狀的錯誤認識如何影響故意與責任","B":"只要甲主觀上害怕，就必然成立客觀正當防衛","C":"只要乙沒有持刀，甲必然成立故意傷害罪且不得討論錯誤","D":"誤想防衛與刑法上的錯誤理論完全無關"},"answer":"A","core":"誤想防衛","explanation":"","basis":"","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 36 題"},{"id":"CRIM45_37","course":"crim_gen2","term":"Y1S2","scopeWeek":3,"type":"mc","q":"甲遭乙徒手攻擊，甲原可用適當力量制止，卻在乙已失去攻擊能力後仍繼續猛烈毆打乙。關於甲的行為，下列何者最適當？","options":{"A":"只要最初存在攻擊，甲之後所有行為均屬正當防衛","B":"正當防衛完全不需要考慮防衛行為的必要性","C":"應區分正在進行的侵害與侵害終了後的行為，不能將全部毆打行為一概認為正當防衛","D":"只要甲曾受傷，乙即喪失刑法保護"},"answer":"C","core":"防衛過當","explanation":"","basis":"刑法 §23","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 37 題"},{"id":"CRIM45_38","course":"crim_gen2","term":"Y1S2","scopeWeek":11,"type":"mc","q":"甲決定殺害乙，購買刀械並事先調查乙的住處，但尚未開始實行殺人構成要件行為。依刑法第25條及第271條，下列何者最適當？","options":{"A":"甲必然成立殺人既遂罪","B":"甲可能成立殺人預備罪","C":"甲必然成立殺人未遂罪","D":"只要尚未著手，法律一律不得處罰任何預備行為"},"answer":"B","core":"預備犯","explanation":"","basis":"刑法 §25、§271 III","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 38 題"},{"id":"CRIM45_39","course":"crim_gen2","term":"Y1S2","scopeWeek":11,"type":"mc","q":"依刑法第25條，關於未遂犯的處罰，下列何者正確？","options":{"A":"所有犯罪的未遂犯一律處罰","B":"未遂犯一律比既遂犯處更重的刑","C":"未遂犯一律免除其刑","D":"未遂犯的處罰，以法律有特別規定者為限"},"answer":"D","core":"未遂犯的處罰","explanation":"","basis":"刑法 §25 II","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 39 題"},{"id":"CRIM45_40","course":"crim_gen1","term":"Y1S1","scopeWeek":14,"type":"mc","q":"甲基於傷害故意毆打乙，導致乙死亡。假設甲對死亡結果欠缺預見可能性，且依具體情況也不能預見。依刑法第17條，下列何者正確？","options":{"A":"不得僅因發生死亡結果，即依加重結果犯規定加重其刑","B":"只要死亡發生，就一律成立傷害致死罪","C":"甲必然成立故意殺人罪","D":"甲必然成立過失致死罪"},"answer":"A","core":"加重結果犯","explanation":"","basis":"刑法 §17","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 40 題"},{"id":"CRIM45_41","course":"crim_gen2","term":"Y1S2","scopeWeek":13,"type":"mc","q":"甲乙共同計畫竊取商店財物，甲負責把風，乙負責進入商店取物。乙在竊盜過程中，因個人恩怨突然故意殺害店員，甲對殺人既未參與謀議，也無共同殺人故意。下列何者最適當？","options":{"A":"甲必然與乙共同成立故意殺人罪","B":"只要共同竊盜，甲即須對乙所有行為負共同正犯責任","C":"乙超出共同犯意範圍的殺人行為，原則上不得當然歸責於甲","D":"甲必然不成立任何犯罪"},"answer":"C","core":"共同正犯・犯意聯絡","explanation":"","basis":"刑法 §28","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 41 題"},{"id":"CRIM45_42","course":"crim_gen2","term":"Y1S2","scopeWeek":14,"type":"mc","q":"甲教唆乙殺害丙，但乙完全不受影響，始終沒有產生殺人犯意，也未著手實行殺人。依刑法第29條及現行刑法的共犯從屬原則，下列何者最適當？","options":{"A":"甲必然成立殺人既遂罪","B":"甲原則上不成立殺人罪的教唆犯","C":"甲必然成立殺人未遂罪","D":"只要甲曾說出教唆言詞，就必然與殺人既遂同刑"},"answer":"B","core":"教唆未遂","explanation":"","basis":"刑法 §29","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 42 題"},{"id":"CRIM45_43","course":"crim_gen2","term":"Y1S2","scopeWeek":16,"type":"mc","q":"甲因故意犯罪受有期徒刑執行完畢，於五年內又故意犯有期徒刑以上之罪。關於刑法第47條及司法院釋字第775號解釋，下列何者正確？","options":{"A":"只要構成累犯，法院一律必須加重最低本刑，不得考量個案","B":"累犯制度已經完全失效，法院不得適用","C":"只有過失犯罪才能成立累犯","D":"法院應注意個案加重處罰是否符合罪刑相當及比例原則，不得機械式一律加重最低本刑"},"answer":"D","core":"累犯","explanation":"","basis":"刑法 §47 I；司法院釋字第 775 號解釋","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 43 題"},{"id":"CRIM45_44","course":"crim_gen2","term":"Y1S2","scopeWeek":16,"type":"mc","q":"甲犯罪後，於具有偵查犯罪職權的公務員尚未發覺其犯罪前，主動向警方坦承犯罪並接受裁判。依刑法第62條，下列何者正確？","options":{"A":"符合自首要件者，得減輕其刑","B":"自首者一律無罪","C":"自首者一律免除其刑","D":"只有犯罪被警方查獲後才可能成立自首"},"answer":"A","core":"自首","explanation":"","basis":"刑法 §62","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 44 題"},{"id":"CRIM45_45","course":"crim_gen2","term":"Y1S2","scopeWeek":16,"type":"mc","q":"甲受二年有期徒刑的宣告，符合刑法第74條所定前科等其他法定要件，法院認為暫不執行為適當。關於緩刑，下列何者正確？","options":{"A":"只要被告請求，法院就必須宣告緩刑","B":"緩刑期間一律為十年","C":"法院得宣告二年以上五年以下的緩刑","D":"宣告緩刑即表示犯罪行為不成立"},"answer":"C","core":"緩刑","explanation":"","basis":"刑法 §74 I","status":"USER_CONFIRMED","source":"刑法_45題_2026-10-14.md 第 45 題"},{"id":"SEC40_01","course":"securities","term":"Y3S1","scopeWeek":5,"type":"mc","q":"禁止內線交易規範的主要目的為何？","options":{"A":"確保所有投資人獲得相同報酬","B":"禁止公司董事持有股票","C":"維護證券市場交易公平性及投資人權益","D":"保證股票價格持續上漲"},"answer":"C","core":"內線交易・規範目的","explanation":"","basis":"","status":"USER_CONFIRMED","source":"證券交易法_40題_2026-10-14.md 第 1 題"},{"id":"SEC40_02","course":"securities","term":"Y3S1","scopeWeek":5,"type":"mc","q":"依證券交易法第157條之1第1項，下列何者原則上屬於內線交易規範的行為主體？","options":{"A":"公司董事、監察人及經理人","B":"所有曾經購買股票的投資人","C":"所有公司的普通員工，不論是否知悉消息","D":"所有證券市場的新聞記者，不論消息來源"},"answer":"A","core":"內線交易・行為主體","explanation":"","basis":"證券交易法 §157-1 I ①","status":"USER_CONFIRMED","source":"證券交易法_40題_2026-10-14.md 第 2 題"},{"id":"SEC40_03","course":"securities","term":"Y3S1","scopeWeek":5,"type":"mc","q":"依證券交易法第157條之1第1項第2款，持有發行股票公司股份超過多少比例的股東，屬於該款規範的行為主體？","options":{"A":"百分之五","B":"百分之八","C":"百分之二十","D":"百分之十"},"answer":"D","core":"內線交易・大股東","explanation":"","basis":"證券交易法 §157-1 I ②","status":"USER_CONFIRMED","source":"證券交易法_40題_2026-10-14.md 第 3 題"},{"id":"SEC40_04","course":"securities","term":"Y3S1","scopeWeek":5,"type":"mc","q":"甲為上市公司委任的律師，因處理併購案件而獲悉尚未公開的重大消息。甲可能依證券交易法第157條之1第1項何款受到規範？","options":{"A":"第1款：公司董事等人員","B":"第3款：基於職業或控制關係獲悉消息之人","C":"第4款：喪失身分未滿六個月之人","D":"第5款：消息受領人"},"answer":"B","core":"內線交易・職業關係","explanation":"","basis":"證券交易法 §157-1 I ③","status":"USER_CONFIRMED","source":"證券交易法_40題_2026-10-14.md 第 4 題"},{"id":"SEC40_05","course":"securities","term":"Y3S1","scopeWeek":5,"type":"mc","q":"依證券交易法第157條之1第1項第4款，喪失同項前三款所定身分後，未滿多久者仍屬規範對象？","options":{"A":"三個月","B":"一年","C":"六個月","D":"二年"},"answer":"C","core":"內線交易・離職人員","explanation":"","basis":"證券交易法 §157-1 I ④","status":"USER_CONFIRMED","source":"證券交易法_40題_2026-10-14.md 第 5 題"},{"id":"SEC40_06","course":"securities","term":"Y3S1","scopeWeek":5,"type":"mc","q":"甲為上市公司經理人，將尚未公開且已明確的重大併購消息告知友人乙。乙實際知悉後，在消息公開前買入該公司股票。下列何者正確？","options":{"A":"乙不是公司員工，必然不受規範","B":"乙可能屬於證券交易法第157條之1第1項第5款的消息受領人","C":"乙只有在取得董事職位後才受規範","D":"乙只有在買入超過公司百分之十股份時才受規範"},"answer":"B","core":"內線交易・消息受領人","explanation":"","basis":"證券交易法 §157-1 I ⑤","status":"USER_CONFIRMED","source":"證券交易法_40題_2026-10-14.md 第 6 題"},{"id":"SEC40_07","course":"securities","term":"Y3S1","scopeWeek":5,"type":"mc","q":"依證券交易法第157條之1第1項，行為主體實際知悉重大消息時，在消息明確後，原則上於何段期間不得買賣相關股票？","options":{"A":"未公開前或公開後十八小時內","B":"僅消息公開前一小時","C":"僅消息公開後三日內","D":"僅董事會開會當日"},"answer":"A","core":"內線交易・交易禁止期間","explanation":"","basis":"證券交易法 §157-1 I","status":"USER_CONFIRMED","source":"證券交易法_40題_2026-10-14.md 第 7 題"},{"id":"SEC40_08","course":"securities","term":"Y3S1","scopeWeek":5,"type":"mc","q":"關於內線交易的成立，下列何者正確？","options":{"A":"必須獲利超過一百萬元","B":"必須使其他投資人實際虧損","C":"必須連續交易三次以上","D":"不以行為人實際獲利為必要"},"answer":"D","core":"內線交易・獲利要件","explanation":"","basis":"","status":"USER_CONFIRMED","source":"證券交易法_40題_2026-10-14.md 第 8 題"},{"id":"SEC40_09","course":"securities","term":"Y3S1","scopeWeek":5,"type":"mc","q":"內線交易行為人以他人名義買賣股票，下列何者正確？","options":{"A":"只要不是本人帳戶，一律不受規範","B":"只有使用配偶帳戶才受規範","C":"證券交易法第157條之1亦禁止符合要件者以他人名義買賣","D":"只有使用公司帳戶才受規範"},"answer":"C","core":"內線交易・交易方式","explanation":"","basis":"證券交易法 §157-1 I","status":"USER_CONFIRMED","source":"證券交易法_40題_2026-10-14.md 第 9 題"},{"id":"SEC40_10","course":"securities","term":"Y3S1","scopeWeek":5,"type":"mc","q":"下列何種事項，在符合重大影響股票價格或正當投資人投資決定等要件時，可能構成內線交易規範的重大消息？","options":{"A":"員工午餐菜單更換","B":"公司重大合併或收購計畫","C":"辦公室影印紙品牌更換","D":"員工個人購買新手機"},"answer":"B","core":"重大消息・企業併購","explanation":"","basis":"證券交易法 §157-1 V","status":"USER_CONFIRMED","source":"證券交易法_40題_2026-10-14.md 第 10 題"},{"id":"SEC40_11","course":"securities","term":"Y3S1","scopeWeek":5,"type":"mc","q":"依重大消息範圍及其公開方式管理辦法第5條，關於重大消息成立時點的認定，下列何者正確？","options":{"A":"一律以股票價格實際上漲日為準","B":"一律以新聞媒體報導日為準","C":"一律以股東會正式通過日為準","D":"依事實發生日、協議日、簽約日、董事會決議日或其他具體事證可得明確之日等，以日期在前者為準"},"answer":"D","core":"重大消息・成立時點","explanation":"","basis":"證券交易法第一百五十七條之一第五項及第六項重大消息範圍及其公開方式管理辦法 §5","status":"USER_CONFIRMED","source":"證券交易法_40題_2026-10-14.md 第 11 題"},{"id":"SEC40_12","course":"securities","term":"Y3S1","scopeWeek":5,"type":"mc","q":"關於證券交易法第157條之1所稱「實際知悉」，下列何者正確？","options":{"A":"須判斷行為人是否實際知悉符合規範的重大消息","B":"只要股票價格上漲，即推定所有買受人實際知悉","C":"只要行為人認識公司員工，即當然實際知悉","D":"不論行為人知悉何種內容，均直接成立內線交易"},"answer":"A","core":"重大消息・實際知悉","explanation":"","basis":"證券交易法 §157-1 I","status":"USER_CONFIRMED","source":"證券交易法_40題_2026-10-14.md 第 12 題"},{"id":"SEC40_13","course":"securities","term":"Y3S1","scopeWeek":5,"type":"mc","q":"甲偶然聽見上市公司員工談及「可能有併購案」，但未聽見具體交易內容。關於甲是否實際知悉重大消息，下列何者正確？","options":{"A":"只要聽到「併購」二字，必然成立內線交易","B":"只要消息是偶然聽見，必然不成立內線交易","C":"應依甲實際獲悉的消息內容及其他具體事證判斷","D":"只要甲買賣股票沒有獲利，必然不成立內線交易"},"answer":"C","core":"消息受領・偶然聽聞","explanation":"","basis":"","status":"USER_CONFIRMED","source":"證券交易法_40題_2026-10-14.md 第 13 題"},{"id":"SEC40_14","course":"securities","term":"Y3S1","scopeWeek":5,"type":"mc","q":"關於內線交易消息傳遞責任的「關係論」，下列何者最符合其理論重點？","options":{"A":"只要股票價格異常波動，即成立責任","B":"重視消息提供人與公司間的信賴義務，以及消息傳遞是否涉及該義務的違反","C":"所有投資人均不得交換任何資訊","D":"只要消息受領人獲利，即推定提供人違反刑法"},"answer":"B","core":"消息傳遞責任・關係論","explanation":"","basis":"","status":"USER_CONFIRMED","source":"證券交易法_40題_2026-10-14.md 第 14 題"},{"id":"SEC40_15","course":"securities","term":"Y3S1","scopeWeek":5,"type":"mc","q":"關於內線交易消息傳遞責任的「市場論」，下列何者最符合其理論基礎？","options":{"A":"保護證券市場資訊流通的公平性與效率","B":"以公司董事是否取得報酬為唯一判準","C":"只保護公司經理人的個人利益","D":"認為消息受領人永遠不受內線交易規範"},"answer":"A","core":"消息傳遞責任・市場論","explanation":"","basis":"","status":"USER_CONFIRMED","source":"證券交易法_40題_2026-10-14.md 第 15 題"},{"id":"SEC40_16","course":"securities","term":"Y3S1","scopeWeek":5,"type":"mc","q":"美國法上Dirks案討論消息傳遞責任時，下列何者屬於重要判斷因素？","options":{"A":"消息受領人是否持有至少一千張股票","B":"消息提供人是否為上市公司董事長","C":"股票交易是否在星期五進行","D":"消息提供人是否違反信賴義務，以及是否涉及個人利益"},"answer":"D","core":"消息傳遞責任・Dirks案","explanation":"","basis":"","status":"USER_CONFIRMED","source":"證券交易法_40題_2026-10-14.md 第 16 題"},{"id":"SEC40_17","course":"securities","term":"Y3S1","scopeWeek":5,"type":"mc","q":"依美國Dirks案相關消息傳遞責任理論，下列何者最符合對消息提供人「個人利益」的理解？","options":{"A":"僅限直接收取現金","B":"僅限取得公司股份","C":"可能包含金錢利益、名譽利益或以消息餽贈親友等情形","D":"只要沒有書面契約，就絕對不存在個人利益"},"answer":"C","core":"消息傳遞責任・個人利益","explanation":"","basis":"","status":"USER_CONFIRMED","source":"證券交易法_40題_2026-10-14.md 第 17 題"},{"id":"SEC40_18","course":"securities","term":"Y3S1","scopeWeek":5,"type":"mc","q":"關於證券交易法第157條之1第1項第5款是否涵蓋間接消息受領人，下列何者正確？","options":{"A":"法條明文規定所有輾轉受領消息者一律無罪","B":"存在文義解釋與市場公平保護範圍的爭議","C":"法條明文規定所有曾聽聞市場傳言者均成立犯罪","D":"只有董事長的直系血親卑親屬才可能成為間接消息受領人"},"answer":"B","core":"間接消息受領人","explanation":"","basis":"證券交易法 §157-1 I ⑤","status":"USER_CONFIRMED","source":"證券交易法_40題_2026-10-14.md 第 18 題"},{"id":"SEC40_19","course":"securities","term":"Y3S1","scopeWeek":5,"type":"mc","q":"依證券交易法第157條之1第3項，違反內線交易規定者，原則上對何者負法定損害賠償責任？","options":{"A":"當日善意從事相反買賣之人","B":"所有持有該公司股票的人，不論交易情形","C":"只有公司的董事長","D":"只有證券交易所"},"answer":"A","core":"內線交易・民事責任","explanation":"","basis":"證券交易法 §157-1 III","status":"USER_CONFIRMED","source":"證券交易法_40題_2026-10-14.md 第 19 題"},{"id":"SEC40_20","course":"securities","term":"Y3S1","scopeWeek":5,"type":"mc","q":"依證券交易法第157條之1第4項，消息受領人對於同條第3項的損害賠償，原則上應與何者負連帶賠償責任？","options":{"A":"所有證券商","B":"所有持有同一股票的投資人","C":"主管機關的全體公務員","D":"同條第1項第1款至第4款提供消息之人，但法律另有免責規定者除外"},"answer":"D","core":"內線交易・連帶賠償責任","explanation":"","basis":"證券交易法 §157-1 IV","status":"USER_CONFIRMED","source":"證券交易法_40題_2026-10-14.md 第 20 題"},{"id":"SEC40_21","course":"securities","term":"Y3S1","scopeWeek":2,"type":"mc","q":"依證券交易法第6條，下列何者正確？","options":{"A":"只有印製紙本的股票才屬有價證券","B":"所有私人借據均當然屬證券交易法上的有價證券","C":"只有上市股票才受證券交易法規範","D":"未印製實體證券的股票，仍可能屬於證券交易法上的有價證券"},"answer":"D","core":"有價證券的範圍","explanation":"","basis":"證券交易法 §6","status":"USER_CONFIRMED","source":"證券交易法_40題_2026-10-14.md 第 21 題"},{"id":"SEC40_22","course":"securities","term":"Y3S1","scopeWeek":2,"type":"mc","q":"依證券交易法第7條，下列何者最符合「募集」與「私募」的區別？","options":{"A":"募集係對非特定人公開招募，私募則依法律規定對特定人招募","B":"募集只能發行公司債，私募只能發行股票","C":"募集不受證券交易法規範，私募才受規範","D":"募集必須在證券交易所進行，私募必須在銀行進行"},"answer":"A","core":"募集與私募","explanation":"","basis":"證券交易法 §7","status":"USER_CONFIRMED","source":"證券交易法_40題_2026-10-14.md 第 22 題"},{"id":"SEC40_23","course":"securities","term":"Y3S1","scopeWeek":2,"type":"mc","q":"依證券交易法第8條，關於有價證券的發行，下列何者正確？","options":{"A":"必須製作實體股票並以人工交付","B":"只有證券交易所可以發行股票","C":"得以帳簿劃撥方式交付有價證券","D":"發行必須以公開競價方式進行"},"answer":"C","core":"有價證券的發行","explanation":"","basis":"證券交易法 §8","status":"USER_CONFIRMED","source":"證券交易法_40題_2026-10-14.md 第 23 題"},{"id":"SEC40_24","course":"securities","term":"Y3S1","scopeWeek":3,"type":"mc","q":"依證券交易法第13條，公開說明書的主要功能為何？","options":{"A":"作為公司員工的勞動契約","B":"發行人為有價證券募集或出賣，依法向公眾提出的說明文書","C":"取代公司的所有財務報告","D":"保證投資人購買股票後一定獲利"},"answer":"B","core":"公開說明書","explanation":"","basis":"證券交易法 §13","status":"USER_CONFIRMED","source":"證券交易法_40題_2026-10-14.md 第 24 題"},{"id":"SEC40_25","course":"securities","term":"Y3S1","scopeWeek":4,"type":"mc","q":"甲公司為吸引投資人購買股票，故意對外發布虛假的營收資料，使投資人誤信公司獲利良好。下列何者最符合證券交易法第20條第1項？","options":{"A":"只有公司已經倒閉才可能違法","B":"只要資料發布在網路上，就不受規範","C":"只要投資人沒有提出抗議，就當然合法","D":"有價證券的募集、發行、私募或買賣，不得有虛偽、詐欺或其他足致他人誤信的行為"},"answer":"D","core":"證券詐欺","explanation":"","basis":"證券交易法 §20 I","status":"USER_CONFIRMED","source":"證券交易法_40題_2026-10-14.md 第 25 題"},{"id":"SEC40_26","course":"securities","term":"Y3S1","scopeWeek":4,"type":"mc","q":"依證券交易法第20條之1，財務報告主要內容有虛偽或隱匿，致投資人受損害時，下列何者正確？","options":{"A":"法律設有發行人及其負責人等人的損害賠償責任","B":"只有股票上漲時才可能成立責任","C":"所有投資人都必須先取得刑事有罪判決才能請求賠償","D":"只有公司員工可以請求賠償"},"answer":"A","core":"財報不實・民事責任","explanation":"","basis":"證券交易法 §20-1 I","status":"USER_CONFIRMED","source":"證券交易法_40題_2026-10-14.md 第 26 題"},{"id":"SEC40_27","course":"securities","term":"Y3S1","scopeWeek":4,"type":"mc","q":"會計師辦理財務報告簽證時，違反業務上應盡的義務，致投資人因財報主要內容不實而受損害。依證券交易法第20條之1，下列何者正確？","options":{"A":"會計師一律不負民事責任","B":"只有發行人可以向會計師請求賠償","C":"符合法定要件時，會計師可能負損害賠償責任","D":"會計師只要取得會計師執照，即永久免責"},"answer":"C","core":"財報不實・會計師責任","explanation":"","basis":"證券交易法 §20-1 III","status":"USER_CONFIRMED","source":"證券交易法_40題_2026-10-14.md 第 27 題"},{"id":"SEC40_28","course":"securities","term":"Y3S1","scopeWeek":7,"type":"mc","q":"依證券交易法第21條，本法規定的損害賠償請求權，自請求權人知有得受賠償的原因時起，原則上經過多久不行使而消滅？","options":{"A":"六個月","B":"二年","C":"十年","D":"二十年"},"answer":"B","core":"證券損害賠償・消滅時效","explanation":"","basis":"證券交易法 §21","status":"USER_CONFIRMED","source":"證券交易法_40題_2026-10-14.md 第 28 題"},{"id":"SEC40_29","course":"securities","term":"Y3S1","scopeWeek":3,"type":"mc","q":"依證券交易法第22條，關於有價證券的募集與發行，下列何者正確？","options":{"A":"原則上應依規定向主管機關申報生效後始得為之，但法律另有規定者除外","B":"任何公司均得不受限制公開募集股票","C":"只要董事長同意，即可免除全部法定程序","D":"只有外國公司需要遵守申報程序"},"answer":"A","core":"公開發行・申報生效","explanation":"","basis":"證券交易法 §22 I","status":"USER_CONFIRMED","source":"證券交易法_40題_2026-10-14.md 第 29 題"},{"id":"SEC40_30","course":"securities","term":"Y3S1","scopeWeek":16,"type":"mc","q":"依證券交易法第28條之2，符合規定的上市或上櫃公司買回自己股份，其買回數量原則上不得超過已發行股份總數的多少？","options":{"A":"百分之五","B":"百分之十五","C":"百分之二十","D":"百分之十"},"answer":"D","core":"庫藏股・買回數量","explanation":"","basis":"證券交易法 §28-2 II","status":"USER_CONFIRMED","source":"證券交易法_40題_2026-10-14.md 第 30 題"},{"id":"SEC40_31","course":"securities","term":"Y3S1","scopeWeek":16,"type":"mc","q":"依證券交易法第28條之2，下列何者屬於上市或上櫃公司得依法買回自己股份的目的？","options":{"A":"無條件讓董事長永久持有公司股份","B":"轉讓股份予員工","C":"避免公司編製財務報告","D":"使公司不再受到主管機關監督"},"answer":"B","core":"庫藏股・法定目的","explanation":"","basis":"證券交易法 §28-2 I ①","status":"USER_CONFIRMED","source":"證券交易法_40題_2026-10-14.md 第 31 題"},{"id":"SEC40_32","course":"securities","term":"Y3S1","scopeWeek":11,"type":"mc","q":"關於公開發行公司獨立董事制度，下列何者最符合其主要功能？","options":{"A":"使公司不必召開董事會","B":"使所有股東均自動成為董事","C":"強化公司治理與董事會監督功能","D":"使獨立董事取代所有經理人執行日常業務"},"answer":"C","core":"獨立董事・制度目的","explanation":"","basis":"","status":"USER_CONFIRMED","source":"證券交易法_40題_2026-10-14.md 第 32 題"},{"id":"SEC40_33","course":"securities","term":"Y3S1","scopeWeek":11,"type":"mc","q":"依證券交易法第14條之4，公開發行公司依法設置審計委員會時，其成員應由何者組成？","options":{"A":"全體獨立董事","B":"全體普通股股東","C":"全體公司員工","D":"全體外部債權人"},"answer":"A","core":"審計委員會・組成","explanation":"","basis":"證券交易法 §14-4 II","status":"USER_CONFIRMED","source":"證券交易法_40題_2026-10-14.md 第 33 題"},{"id":"SEC40_34","course":"securities","term":"Y3S1","scopeWeek":10,"type":"mc","q":"依證券交易法第43條之1第1項，任何人單獨或與他人共同取得任一公開發行公司已發行股份總額超過多少比例者，原則上應依法申報及公告？","options":{"A":"百分之三","B":"百分之五","C":"百分之十","D":"百分之二十"},"answer":"B","core":"大量取得股份・申報","explanation":"","basis":"證券交易法 §43-1 I","status":"USER_CONFIRMED","source":"證券交易法_40題_2026-10-14.md 第 34 題"},{"id":"SEC40_35","course":"securities","term":"Y3S1","scopeWeek":10,"type":"mc","q":"關於證券交易法上的公開收購制度，下列何者正確？","options":{"A":"公開收購必須取得每位股東個別同意後才能公告","B":"公開收購只能由發行公司自己進行","C":"公開收購不需要遵守任何資訊揭露義務","D":"公開收購係依法律所定程序，向非特定人公開提出收購有價證券的要約"},"answer":"D","core":"公開收購","explanation":"","basis":"證券交易法 §43-1 II","status":"USER_CONFIRMED","source":"證券交易法_40題_2026-10-14.md 第 35 題"},{"id":"SEC40_36","course":"securities","term":"Y3S1","scopeWeek":2,"type":"mc","q":"依證券交易法第43條之6，公開發行公司依法辦理私募有價證券，原則上須經股東會何種決議？","options":{"A":"出席股東過半數同意即可，不論出席股數","B":"全體股東一致同意","C":"代表已發行股份總數過半數股東出席，出席股東表決權三分之二以上同意","D":"董事長單獨決定即可"},"answer":"C","core":"私募・股東會決議","explanation":"","basis":"證券交易法 §43-6 I","status":"USER_CONFIRMED","source":"證券交易法_40題_2026-10-14.md 第 36 題"},{"id":"SEC40_37","course":"securities","term":"Y3S1","scopeWeek":5,"type":"mc","q":"依證券交易法第157條，發行股票公司的董事、監察人、經理人或持股超過百分之十的股東，對公司上市股票於取得後六個月內再行賣出，因而獲得利益時，原則上如何處理？","options":{"A":"公司應請求將利益歸於公司","B":"利益一律由證券交易所取得","C":"利益一律由交易相對人取得","D":"只要交易合法交割，利益即絕對不得請求歸入"},"answer":"A","core":"短線交易・歸入權","explanation":"","basis":"證券交易法 §157 I","status":"USER_CONFIRMED","source":"證券交易法_40題_2026-10-14.md 第 37 題"},{"id":"SEC40_38","course":"securities","term":"Y3S1","scopeWeek":5,"type":"mc","q":"依證券交易法第157條第2項，公司董事會或監察人不行使短線交易利益歸入請求權時，股東得定多久期限請求董事或監察人行使，逾期不行使時，得為公司行使？","options":{"A":"七日","B":"十五日","C":"六十日","D":"三十日"},"answer":"D","core":"短線交易・股東代位行使","explanation":"","basis":"證券交易法 §157 II","status":"USER_CONFIRMED","source":"證券交易法_40題_2026-10-14.md 第 38 題"},{"id":"SEC40_39","course":"securities","term":"Y3S1","scopeWeek":6,"type":"mc","q":"甲為製造某上市股票交易熱絡的假象，以自己控制的不同帳戶連續委託買賣，使買賣申報相對成交。下列何者最符合其可能涉及的違法類型？","options":{"A":"內線交易","B":"操縱市場","C":"公司法上的普通贈與","D":"民法上的無因管理"},"answer":"B","core":"操縱市場・相對成交","explanation":"","basis":"證券交易法 §155 I ⑤","status":"USER_CONFIRMED","source":"證券交易法_40題_2026-10-14.md 第 39 題"},{"id":"SEC40_40","course":"securities","term":"Y3S1","scopeWeek":6,"type":"mc","q":"甲為影響某上市股票價格，故意散布該公司即將獲得重大訂單的不實消息。依證券交易法第155條第1項，下列何者正確？","options":{"A":"只要消息發布在社群平台，就必然合法","B":"只有公司董事長散布不實消息才可能違法","C":"意圖影響證券交易價格而散布流言或不實資料，可能構成操縱市場行為","D":"只要甲沒有實際買賣股票，就必然不受證券交易法規範"},"answer":"C","core":"操縱市場・散布不實資訊","explanation":"","basis":"證券交易法 §155 I ⑥","status":"USER_CONFIRMED","source":"證券交易法_40題_2026-10-14.md 第 40 題"},{"id":"Y4_CJS_01","course":"crim_judgment_sem","term":"Y4S1","scopeWeek":2,"type":"mc","q":"依刑事訴訟法第308條，有罪之判決書除了主文與理由之外，還應記載什麼？","options":{"A":"犯罪事實","B":"被告的財產清單","C":"檢察官的起訴書全文","D":"被害人的書面陳述"},"answer":"A","core":"判決書應分別記載其裁判之主文與理由；有罪之判決書並應記載犯罪事實，且得與理由合併記載。","basis":"刑事訴訟法 §308","status":"Y4_CROSS_REVIEWED","source":"AA_Y4"},{"id":"Y4_CJS_02","course":"crim_judgment_sem","term":"Y4S1","scopeWeek":3,"type":"mc","q":"甲把乙推倒以後，已經轉身走遠。乙爬起來追上去，從背後打了甲一拳。乙能不能主張正當防衛？","options":{"A":"可以，因為甲先動手","B":"可以，只要乙打得不重","C":"不可以，侵害已經過去，不是「現在」不法之侵害","D":"可以，只要乙事後去報警"},"answer":"C","core":"正當防衛須對於現在不法之侵害；侵害已經結束以後的反擊不是防衛。防衛過當者，得減輕或免除其刑，但前提仍是現在不法之侵害。","basis":"中華民國刑法 §23","status":"Y4_CROSS_REVIEWED","source":"AA_Y4"},{"id":"Y4_CJS_03","course":"crim_judgment_sem","term":"Y4S1","scopeWeek":5,"type":"mc","q":"刑法第57條規定，科刑時應以什麼為基礎，並審酌一切情狀？","options":{"A":"被害人的要求","B":"社會輿論","C":"檢察官的求刑","D":"行為人之責任"},"answer":"D","core":"科刑時應以行為人之責任為基礎，並審酌一切情狀，尤應注意第57條列舉的十款事項。","basis":"中華民國刑法 §57","status":"Y4_CROSS_REVIEWED","source":"AA_Y4"},{"id":"Y4_CJS_04","course":"crim_judgment_sem","term":"Y4S1","scopeWeek":4,"type":"mc","q":"依刑事訴訟法第155條，證據的證明力由誰、怎麼判斷？","options":{"A":"由檢察官決定","B":"由法院本於確信自由判斷，但不得違背經驗法則及論理法則","C":"依證據的數量多寡決定","D":"由被告決定"},"answer":"B","core":"證據之證明力，由法院本於確信自由判斷，但不得違背經驗法則及論理法則；無證據能力、未經合法調查之證據，不得作為判斷之依據。","basis":"刑事訴訟法 §155 I、II","status":"Y4_CROSS_REVIEWED","source":"AA_Y4"},{"id":"Y4_CJS_05","course":"crim_judgment_sem","term":"Y4S1","scopeWeek":10,"type":"mc","q":"法院審理後，認為不能證明被告犯罪。依刑事訴訟法第301條應如何判決？","options":{"A":"諭知無罪之判決","B":"諭知免訴之判決","C":"諭知不受理之判決","D":"裁定延長羈押，繼續調查"},"answer":"A","core":"不能證明被告犯罪或其行為不罰者，應諭知無罪之判決；免訴、不受理是程序上的其他原因。","basis":"刑事訴訟法 §301 I","status":"Y4_CROSS_REVIEWED","source":"AA_Y4"},{"id":"Y4_CJS_06","course":"crim_judgment_sem","term":"Y4S1","scopeWeek":11,"type":"mc","q":"被告被起訴的罪名，最輕本刑為五年有期徒刑。他在審判中沒有選任辯護人。依刑事訴訟法第31條，審判長應如何？","options":{"A":"照常審判，有沒有辯護人是被告自己的事","B":"應指定公設辯護人或律師為被告辯護","C":"等被告聲請才指定","D":"改用簡易程序，不需要辯護人"},"answer":"B","core":"最輕本刑為三年以上有期徒刑案件，於審判中未經選任辯護人者，審判長應指定公設辯護人或律師為被告辯護（強制辯護）。","basis":"刑事訴訟法 §31 I ①","status":"Y4_CROSS_REVIEWED","source":"AA_Y4"},{"id":"Y4_CJS_07","course":"crim_judgment_sem","term":"Y4S1","scopeWeek":12,"type":"mc","q":"依國民法官法第5條，下列經檢察官起訴、由地方法院管轄的第一審案件，何者應行國民參與審判？","options":{"A":"少年刑事案件","B":"犯毒品危害防制條例之罪的案件","C":"所犯最輕本刑為十年以上有期徒刑之罪的案件","D":"所有財產犯罪的案件"},"answer":"C","core":"應行國民參與審判的是所犯最輕本刑為十年以上有期徒刑之罪，或故意犯罪因而發生死亡結果者；少年刑事案件和犯毒品危害防制條例之罪的案件除外。","basis":"國民法官法 §5 I","status":"Y4_CROSS_REVIEWED","source":"AA_Y4"},{"id":"Y4_CJS_08","course":"crim_judgment_sem","term":"Y4S1","scopeWeek":14,"type":"mc","q":"判決確定後，發見該案件的審判係違背法令。依刑事訴訟法第441條，誰得向最高法院提起非常上訴？","options":{"A":"被告本人","B":"原審法官","C":"被害人","D":"最高檢察署檢察總長"},"answer":"D","core":"判決確定後，發見該案件之審判係違背法令者，最高檢察署檢察總長得向最高法院提起非常上訴；被告、法官、被害人都不能自己提起。","basis":"刑事訴訟法 §441","status":"Y4_CROSS_REVIEWED","source":"AA_Y4"},{"id":"Y4_ENF_01","course":"enforcement","term":"Y4S1","scopeWeek":2,"type":"mc","q":"甲持有乙親筆簽名的借據，乙到期不還。甲可不可以直接拿這張借據，向法院聲請強制執行？","options":{"A":"可以，借據本身就是執行名義","B":"可以，只要借據經過公證人認證簽名","C":"不可以，要先取得強制執行法第4條所列的執行名義，例如確定判決，或債務人未異議的支付命令","D":"不可以，借款債權依法不能強制執行"},"answer":"C","core":"借據只是證明借款的私文書，不在強制執行法第4條的執行名義裡。公證人「認證」只證明私文書的簽名真正，和載明應逕受強制執行的「公證書」不同。要先取得確定判決，或支付命令（債務人未於法定期間合法異議）等執行名義。","basis":"強制執行法 §4 I；公證法 §2 I、§13 I；民事訴訟法 §521 I","status":"Y4_CROSS_REVIEWED","source":"AA_Y4"},{"id":"Y4_ENF_02","course":"enforcement","term":"Y4S1","scopeWeek":12,"type":"mc","q":"法院強制執行時，查封了債務人乙家中的一架鋼琴，但這架鋼琴其實是鄰居丙寄放的，所有權屬於丙。丙在強制執行程序終結前，最適合提起什麼訴訟？","options":{"A":"債務人異議之訴","B":"第三人異議之訴","C":"再審之訴","D":"確認支付命令無效之訴"},"answer":"B","core":"第三人就執行標的物有足以排除強制執行的權利（例如所有權），得於強制執行程序終結前，向執行法院對債權人提起異議之訴。債務人異議之訴是債務人主張請求權消滅或妨礙的事由。","basis":"強制執行法 §15、§14","status":"Y4_CROSS_REVIEWED","source":"AA_Y4"},{"id":"Y4_ENF_03","course":"enforcement","term":"Y4S1","scopeWeek":13,"type":"mc","q":"確定判決命乙清償 50 萬元。判決確定後，乙已經全部清償，債權人甲仍持判決聲請強制執行。乙在執行程序終結前，可以提起什麼訴訟？","options":{"A":"債務人異議之訴","B":"第三人異議之訴","C":"第三審上訴","D":"非常上訴"},"answer":"A","core":"執行名義成立後，有消滅或妨礙債權人請求的事由（例如清償）發生，債務人得於強制執行程序終結前提起債務人異議之訴。判決已經確定，不能再上訴；非常上訴是刑事訴訟的程序。","basis":"強制執行法 §14 I","status":"Y4_CROSS_REVIEWED","source":"AA_Y4"},{"id":"Y4_ENF_04","course":"enforcement","term":"Y4S1","scopeWeek":6,"type":"mc","q":"乙月薪 6 萬元（自然人因提供勞務而獲得的繼續性報酬）。債權人聲請扣押乙的薪資，執行法院沒有認定有失公平的特殊情形。每個月原則上最多可以扣押多少？","options":{"A":"6,000 元","B":"12,000 元","C":"15,000 元","D":"20,000 元"},"answer":"D","core":"對自然人因提供勞務而獲得的繼續性報酬債權發扣押命令，不得逾各期給付數額三分之一：60,000 ÷ 3 ＝ 20,000 元。執行法院認有失公平時得不受比例限制，但應預酌留債務人生活費用。","basis":"強制執行法 §115-1 II、III","status":"Y4_CROSS_REVIEWED","source":"AA_Y4"},{"id":"Y4_ENF_05","course":"enforcement","term":"Y4S1","scopeWeek":15,"type":"mc","q":"執行人員到作家乙家裡查封，看到：一部還沒發表的小說手稿、一支名牌手錶、一輛很少開的跑車、乙名下另一間出租的房子。依強制執行法第53條，哪一樣原則上不得查封？","options":{"A":"名牌手錶","B":"還沒發表的小說手稿","C":"很少開的跑車","D":"另一間出租的房子"},"answer":"B","core":"尚未發表之發明或著作不得查封；其他是可以查封的一般財產。","basis":"強制執行法 §53 I ⑥","status":"Y4_CROSS_REVIEWED","source":"AA_Y4"},{"id":"Y4_ENF_06","course":"enforcement","term":"Y4S1","scopeWeek":14,"type":"mc","q":"甲起訴請求乙返還借款 100 萬元，擔心訴訟期間乙把財產脫手、日後判決贏了也拿不到錢。甲為了保全將來的強制執行，應聲請哪一種保全程序？","options":{"A":"假處分","B":"假執行","C":"定暫時狀態之處分","D":"假扣押"},"answer":"D","core":"金錢請求或得易為金錢請求之請求，欲保全強制執行者，聲請假扣押；金錢請求以外的請求才是假處分。","basis":"民事訴訟法 §522 I、§532 I","status":"Y4_CROSS_REVIEWED","source":"AA_Y4"},{"id":"Y4_ENF_07","course":"enforcement","term":"Y4S1","scopeWeek":3,"type":"mc","q":"下列哪一個機關辦理「民事」強制執行事務？","options":{"A":"法務部行政執行署及其所屬機關","B":"地方檢察署","C":"地方法院及其分院的民事執行處","D":"高等行政法院"},"answer":"C","core":"民事強制執行事務，於地方法院及其分院設民事執行處辦理。行政執行署處理的是公法上金錢給付義務逾期不履行的行政執行，不是民事強制執行。","basis":"強制執行法 §1 I；行政執行法 §4 I","status":"Y4_CROSS_REVIEWED","source":"AA_Y4"},{"id":"Y4_ENF_08","course":"enforcement","term":"Y4S1","scopeWeek":11,"type":"mc","q":"確定判決命乙拆除他在甲土地上搭建的鐵皮屋（這是別人也能代為完成的行為），乙一直不拆。執行法院原則上可以怎麼做？","options":{"A":"以乙的費用，命第三人代為履行","B":"只能對乙處怠金，不能找別人拆","C":"直接管收乙，直到他自己拆","D":"駁回聲請，因為「行為」不能強制執行"},"answer":"A","core":"債務人應為一定行為而不為，且該行為可以由他人代為時，執行法院得以債務人之費用命第三人代為履行。怠金、管收是用在別人無法代為履行的行為。","basis":"強制執行法 §127 I、§128 I","status":"Y4_CROSS_REVIEWED","source":"AA_Y4"},{"id":"Y4_LSO_06","course":"labor_social","term":"Y4S1","scopeWeek":10,"type":"mc","q":"依社會救助法第4條，最低生活費是參照當地區最近一年每人可支配所得中位數的百分之多少訂定？","options":{"A":"百分之四十","B":"百分之五十","C":"百分之六十","D":"百分之七十"},"answer":"C","core":"最低生活費由主管機關參照中央主計機關公布的當地區最近一年每人可支配所得中位數百分之六十定之。","basis":"社會救助法 §4 II","status":"Y4_CROSS_REVIEWED","source":"AA_Y4"},{"id":"Y4_LSO_08","course":"labor_social","term":"Y4S1","scopeWeek":5,"type":"mc","q":"年滿十五歲、無一定雇主而參加職業工會的會員，參加勞工職業災害保險時，以誰為投保單位？","options":{"A":"勞動部","B":"自己","C":"最近一次僱用他的雇主","D":"所屬的職業工會（所屬團體）"},"answer":"D","core":"無一定雇主或自營作業而參加職業工會之會員，應以其所屬團體為投保單位。","basis":"勞工職業災害保險及保護法 §7 ①","status":"Y4_CROSS_REVIEWED","source":"AA_Y4"},{"id":"Y4_ETH_01","course":"legal_ethics","term":"Y4S1","scopeWeek":2,"type":"mc","q":"甲律師受乙委任處理離婚案件，乙在諮詢時說了一件家裡的私事。案件結束、委任終止一年後，有記者打電話來問這件事。依律師法，甲律師應如何？","options":{"A":"不可以說；律師有保守其職務上所知悉秘密之權利及義務，法律另有規定者除外","B":"可以說，委任關係已經結束","C":"可以說，只要記者答應不寫出乙的名字","D":"可以說，保密只限刑事案件"},"answer":"A","core":"律師有保守其職務上所知悉秘密之權利及義務；但法律另有規定者，不在此限。條文沒有「委任結束就免除」或「只限刑事」的限制。","basis":"律師法 §36","status":"Y4_CROSS_REVIEWED","source":"AA_Y4"},{"id":"Y4_ETH_02","course":"legal_ethics","term":"Y4S1","scopeWeek":3,"type":"mc","q":"甲律師同一事務所的同事，曾經受乙委任處理乙與丙之間的糾紛。現在丙想委任甲律師，就同一事件對抗乙。依律師法第34條，下列何者正確？","options":{"A":"甲可以直接受任，因為受過乙委任的不是甲本人","B":"甲只要告知丙這件事，就可以受任","C":"甲不得執行職務；但經利益受影響之當事人全體書面同意，仍得受任","D":"甲不得受任，而且任何情況下都不能補正"},"answer":"C","core":"本人或同一律師事務所之律師曾受委任人之相對人之委任者，律師不得執行職務；這一款的情形，經利益受影響之當事人全體書面同意，仍得受任。","basis":"律師法 §34 I ①、II","status":"Y4_CROSS_REVIEWED","source":"AA_Y4"},{"id":"Y4_ETH_03","course":"legal_ethics","term":"Y4S1","scopeWeek":11,"type":"mc","q":"檢察官偵查時，發現一段可能證明被告當時不在場的監視器畫面。依刑事訴訟法第2條，檢察官應如何？","options":{"A":"交給辯護人處理就好，檢察官只負責不利的證據","B":"只有被告提出請求時才要調查","C":"等到審判時再由法官決定要不要看","D":"對被告有利及不利的情形，一律注意"},"answer":"D","core":"實施刑事訴訟程序之公務員，就該管案件，應於被告有利及不利之情形，一律注意（客觀義務）；被告也得請求為有利於己之必要處分。","basis":"刑事訴訟法 §2","status":"Y4_CROSS_REVIEWED","source":"AA_Y4"},{"id":"Y4_ETH_04","course":"legal_ethics","term":"Y4S1","scopeWeek":10,"type":"mc","q":"下列何者是刑事訴訟法第17條規定，法官應自行迴避、不得執行職務的情形？","options":{"A":"法官曾在報紙上評論過同類型的案件","B":"法官為該案件的被害人","C":"法官和被告畢業於同一所大學","D":"法官住在被告家附近"},"answer":"B","core":"法官為被害人者，應自行迴避。其他選項不是第17條列舉的事由（是否有偏頗之虞，另依聲請迴避的規定判斷）。","basis":"刑事訴訟法 §17 ①","status":"Y4_CROSS_REVIEWED","source":"AA_Y4"},{"id":"Y4_ETH_05","course":"legal_ethics","term":"Y4S1","scopeWeek":12,"type":"mc","q":"辯護人在偵查中因執行職務知悉的事項，可不可以向媒體公開？","options":{"A":"可以，偵查不公開只拘束檢察官與警察","B":"原則上不得公開或揭露予執行法定職務必要範圍以外之人員；但依法令或為維護公共利益或保護合法權益有必要者除外","C":"只要被告同意，就一律可以","D":"只有起訴以後才禁止"},"answer":"B","core":"刑事訴訟法第245條明文把辯護人列入：除依法令或為維護公共利益或保護合法權益有必要者外，偵查中因執行職務知悉之事項，不得公開或揭露予執行法定職務必要範圍以外之人員。","basis":"刑事訴訟法 §245","status":"Y4_CROSS_REVIEWED","source":"AA_Y4"},{"id":"Y4_ETH_06","course":"legal_ethics","term":"Y4S1","scopeWeek":7,"type":"mc","q":"依律師法第37條，律師參與法律扶助、平民法律服務或其他社會公益活動是？","options":{"A":"律師應參與的事項","B":"完全由律師自由決定，法律沒有規定","C":"只有公設辯護人需要","D":"只有執業未滿五年的律師需要"},"answer":"A","core":"律師應參與法律扶助、平民法律服務或其他社會公益活動；種類、最低時數等由全國律師聯合會訂定。","basis":"律師法 §37","status":"Y4_CROSS_REVIEWED","source":"AA_Y4"},{"id":"Y4_ETH_07","course":"legal_ethics","term":"Y4S1","scopeWeek":14,"type":"mc","q":"依律師法第40條，下列何者是律師不得做的事？","options":{"A":"在事務所網站上如實介紹自己的學歷與經歷","B":"參加律師公會舉辦的免費法律講座","C":"向委任人說明酬金的計算方法","D":"挑唆訴訟，或以誇大不實、不正當之方法推展業務"},"answer":"D","core":"律師不得挑唆訴訟，或以誇大不實、不正當之方法推展業務；推展業務的細部限制在律師倫理規範。如實介紹學經歷、參加公益講座、說明酬金都不在第40條禁止之列。","basis":"律師法 §40","status":"Y4_CROSS_REVIEWED","source":"AA_Y4"},{"id":"Y4_ETH_08","course":"legal_ethics","term":"Y4S1","scopeWeek":15,"type":"mc","q":"依律師法第47條，律師收取酬金時應如何？","options":{"A":"等案件結束再依結果決定，事前不必說明","B":"一律按小時計費","C":"應向委任人明示收取酬金之計算方法及數額","D":"酬金一律由法院決定"},"answer":"C","core":"律師應向委任人明示其收取酬金之計算方法及數額。","basis":"律師法 §47","status":"Y4_CROSS_REVIEWED","source":"AA_Y4"},{"id":"Y4_MAR_01","course":"maritime","term":"Y4S2","scopeWeek":2,"type":"mc","q":"依海商法第1條，海商法所稱的船舶是指什麼？","options":{"A":"只限在海上航行的船舶","B":"在海上航行，或在與海相通之水面或水中航行之船舶","C":"只限總噸位一百噸以上的船舶","D":"所有在湖泊航行的船舶"},"answer":"B","core":"本法稱船舶者，謂在海上航行，或在與海相通之水面或水中航行之船舶。","basis":"海商法 §1","status":"Y4_CROSS_REVIEWED","source":"AA_Y4"},{"id":"Y4_MAR_04","course":"maritime","term":"Y4S2","scopeWeek":4,"type":"mc","q":"依海商法第53條，載貨證券由誰、在什麼時候發給？","options":{"A":"運送人或船長於貨物裝載後，因託運人之請求發給","B":"港務機關於船舶出港時主動發給","C":"受貨人於收貨後簽發","D":"海關於報關完成時發給"},"answer":"A","core":"運送人或船長於貨物裝載後，因託運人之請求，應發給載貨證券。","basis":"海商法 §53","status":"Y4_CROSS_REVIEWED","source":"AA_Y4"},{"id":"Y4_PJS_01","course":"public_judgment_sem","term":"Y4S1","scopeWeek":12,"type":"mc","q":"依憲法訴訟法第59條，人民聲請憲法法庭為宣告違憲之判決，應於什麼期間內聲請？","options":{"A":"自用盡審級救濟之最終裁判送達後翌日起之六個月不變期間內","B":"隨時都可以聲請","C":"判決確定後十年內","D":"第一審判決後三十日內"},"answer":"A","core":"聲請應自用盡審級救濟之最終裁判送達後翌日起之六個月不變期間內為之。","basis":"憲法訴訟法 §59 II","status":"Y4_CROSS_REVIEWED","source":"AA_Y4"},{"id":"Y4_PJS_02","course":"public_judgment_sem","term":"Y4S1","scopeWeek":12,"type":"mc","q":"依憲法訴訟法第59條，人民聲請憲法法庭宣告不利確定終局裁判或其所適用之法規範違憲，前提之一是什麼？","options":{"A":"須經十位以上立法委員連署","B":"須先向監察院陳情","C":"須經依法定程序用盡審級救濟程序","D":"只要對法律內容不滿意即可"},"answer":"C","core":"人民於其憲法上所保障之權利遭受不法侵害，經依法定程序用盡審級救濟程序，對於所受不利確定終局裁判，或該裁判及其所適用之法規範，認有牴觸憲法者，才能聲請。","basis":"憲法訴訟法 §59 I","status":"Y4_CROSS_REVIEWED","source":"AA_Y4"},{"id":"Y4_PJS_03","course":"public_judgment_sem","term":"Y4S1","scopeWeek":2,"type":"mc","q":"依憲法訴訟法第35條，大法官贊成裁判的主文，但對理由有補充或不同意見，得提出什麼？","options":{"A":"不同意見書","B":"協同意見書","C":"再審聲請書","D":"抗告狀"},"answer":"B","core":"贊成主文而對理由有補充或不同意見者，得提出協同意見書；對主文曾表示部分或全部不同意見者，才是不同意見書。","basis":"憲法訴訟法 §35","status":"Y4_CROSS_REVIEWED","source":"AA_Y4"},{"id":"Y4_PJS_04","course":"public_judgment_sem","term":"Y4S1","scopeWeek":5,"type":"mc","q":"公務員怠於執行職務，致人民自由或權利遭受損害。依國家賠償法第2條，國家是否負損害賠償責任？","options":{"A":"不負，國家只對公務員積極的行為負責","B":"不負，應由公務員個人全部負責","C":"只有公共設施的損害才由國家賠償","D":"應負損害賠償責任"},"answer":"D","core":"國家賠償法第2條第2項後段：公務員怠於執行職務，致人民自由或權利遭受損害者亦同（國家應負損害賠償責任）。","basis":"國家賠償法 §2 II","status":"Y4_CROSS_REVIEWED","source":"AA_Y4"},{"id":"Y4_PJS_05","course":"public_judgment_sem","term":"Y4S1","scopeWeek":5,"type":"mc","q":"乙走在人行道上，被一個沒有修補的大坑洞絆倒受傷，想請求國家賠償。依國家賠償法第10條，乙第一步應該怎麼做？","options":{"A":"先以書面向賠償義務機關請求","B":"直接向地方法院起訴","C":"先提起訴願","D":"先向監察院陳情"},"answer":"A","core":"依國家賠償法請求損害賠償時，應先以書面向賠償義務機關請求，賠償義務機關應即與請求權人協議（協議先行）；公共設施設置或管理有欠缺的責任依第3條。","basis":"國家賠償法 §10 I、§3 I","status":"Y4_CROSS_REVIEWED","source":"AA_Y4"},{"id":"Y4_PJS_06","course":"public_judgment_sem","term":"Y4S1","scopeWeek":6,"type":"mc","q":"下列何者「不是」行政程序法第7條規定的原則？","options":{"A":"採取之方法應有助於目的之達成","B":"有多種同樣能達成目的之方法時，應選擇對人民權益損害最少者","C":"採取之方法所造成之損害不得與欲達成目的之利益顯失均衡","D":"只要目的正當，可以選擇對人民損害最大但最有效率的方法"},"answer":"D","core":"行政程序法第7條是比例原則的三個子原則：適當性、必要性（損害最少）、衡平性（不得顯失均衡）。","basis":"行政程序法 §7","status":"Y4_CROSS_REVIEWED","source":"AA_Y4"},{"id":"Y4_PJS_07","course":"public_judgment_sem","term":"Y4S1","scopeWeek":4,"type":"mc","q":"人民依法向機關申請補助，被機關以處分駁回。人民認為駁回違法、權利受損害，經訴願程序後，最適合提起哪一種行政訴訟，請求機關作成准許的處分？","options":{"A":"撤銷訴訟","B":"課予義務訴訟（請求應為行政處分或應為特定內容之行政處分）","C":"民事損害賠償訴訟","D":"確認行政處分無效訴訟"},"answer":"B","core":"依法申請之案件被駁回，認為權利受違法損害者，經訴願程序後，得提起請求該機關應為行政處分或應為特定內容之行政處分之訴訟（課予義務訴訟）；只撤銷駁回處分，拿不到准許的處分。","basis":"行政訴訟法 §5 II","status":"Y4_CROSS_REVIEWED","source":"AA_Y4"},{"id":"Y4_PJS_08","course":"public_judgment_sem","term":"Y4S1","scopeWeek":13,"type":"mc","q":"人民因機關的違法行政處分而權利受損害，依行政訴訟法第4條提起撤銷訴訟以前，原則上應先經過什麼程序？","options":{"A":"調解","B":"仲裁","C":"訴願","D":"國家賠償的協議"},"answer":"C","core":"撤銷訴訟原則上須經依訴願法提起訴願而不服其決定（或訴願逾期不為決定）後，才能提起。","basis":"行政訴訟法 §4 I","status":"Y4_CROSS_REVIEWED","source":"AA_Y4"},{"id":"Y4_TAX_03","course":"tax_law","term":"Y4S1","scopeWeek":11,"type":"mc","q":"依納稅者權利保護法第7條，稅捐稽徵機關認定課徵租稅之構成要件事實時，應以什麼為依據？","options":{"A":"契約上記載的名義","B":"實質經濟事實關係及其所生實質經濟利益之歸屬與享有","C":"當年度的稅收預算目標","D":"納稅者的口頭說明"},"answer":"B","core":"實質課稅原則：以實質經濟事實關係及其所生實質經濟利益之歸屬與享有為依據（原本稅捐稽徵法第12條之1的規定已刪除，移到這裡）。","basis":"納稅者權利保護法 §7 II","status":"Y4_CROSS_REVIEWED","source":"AA_Y4"},{"id":"Y4_TAX_06","course":"tax_law","term":"Y4S1","scopeWeek":2,"type":"mc","q":"依所得稅法第71條，綜合所得稅結算申報原則上在什麼期間辦理？","options":{"A":"每年一月一日起至一月三十一日止","B":"每年三月一日起至三月三十一日止","C":"每年五月一日起至五月三十一日止","D":"每年十二月一日起至十二月三十一日止"},"answer":"C","core":"納稅義務人應於每年五月一日起至五月三十一日止辦理結算申報（實務上偶有延長，以當年公告為準）。","basis":"所得稅法 §71 I","status":"Y4_CROSS_REVIEWED","source":"AA_Y4"},{"id":"Y4_TAX_08","course":"tax_law","term":"Y4S1","scopeWeek":4,"type":"mc","q":"遺產及贈與稅法所稱的「贈與」，是指什麼？","options":{"A":"任何金錢的移轉","B":"只限不動產的移轉","C":"只限父母給子女的財產","D":"財產所有人以自己之財產無償給予他人，經他人允受而生效力之行為"},"answer":"D","core":"本法稱贈與，指財產所有人以自己之財產無償給予他人，經他人允受而生效力之行為。","basis":"遺產及贈與稅法 §4 II","status":"Y4_CROSS_REVIEWED","source":"AA_Y4"},{"id":"Y4IP_01","course":"ip_law","term":"Y4S1","scopeWeek":2,"type":"mc","q":"大學生甲寫完一首歌，沒有向任何機關登記，也還沒有公開發表。依著作權法，甲從什麼時候開始享有著作權？","options":{"A":"著作完成時","B":"向經濟部智慧財產局登記以後","C":"公開發表以後","D":"出版或上架販售以後"},"answer":"A","core":"著作權的取得｜著作人於著作完成時享有著作權（創作保護主義，不需登記）。","explanation":"著作權法第10條本文：著作人於著作完成時享有著作權。我國著作權不採登記制度，也不以公開發表為要件。","basis":"著作權法 §10","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4IP_02","course":"ip_law","term":"Y4S1","scopeWeek":2,"type":"mc","q":"依著作權法第9條，下列何者「可以」成為著作權的標的？","options":{"A":"法律條文","B":"依法令舉行的國家考試試題","C":"單純為傳達事實的新聞報導所作成的語文著作","D":"大學生自己拍攝並剪接完成的短片"},"answer":"D","core":"不得為著作權標的的著作｜憲法、法律、命令、公文、依法令舉行的考試試題、單純傳達事實的新聞報導等，不受著作權保護。","explanation":"第9條第1項列舉不得為著作權標的者：憲法、法律、命令或公文；機關就前款作成的翻譯物或編輯物；標語及通用符號、名詞、公式等；單純為傳達事實之新聞報導所作成之語文著作；依法令舉行之各類考試試題及其備用試題。學生自己拍攝剪接的短片不在其中，具原創性即可受保護。","basis":"著作權法 §9","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4IP_03","course":"ip_law","term":"Y4S1","scopeWeek":3,"type":"mc","q":"依著作權法第10條之1，著作權的保護及於下列何者？","options":{"A":"著作所表達的思想","B":"著作中描述的操作方法","C":"著作的表達","D":"著作中提到的發現與原理"},"answer":"C","core":"思想與表達二分｜著作權只保護表達，不保護思想、程序、製程、系統、操作方法、概念、原理、發現。","explanation":"第10條之1：依本法取得之著作權，其保護僅及於該著作之表達，而不及於其所表達之思想、程序、製程、系統、操作方法、概念、原理、發現。","basis":"著作權法 §10-1","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4IP_04","course":"ip_law","term":"Y4S1","scopeWeek":4,"type":"mc","q":"依著作權法第65條第2項，判斷著作的利用是否為合理使用時，下列何者「不是」法律明定應特別注意的判斷基準？","options":{"A":"利用的目的及性質，包括是商業目的或非營利教育目的","B":"利用人是不是學生","C":"所利用的質量及其在整個著作所占的比例","D":"利用結果對著作潛在市場與現在價值的影響"},"answer":"B","core":"合理使用的判斷｜審酌一切情狀，尤應注意：利用的目的及性質、著作的性質、利用的質量及比例、對市場與價值的影響。","explanation":"第65條第1項：著作之合理使用，不構成著作財產權之侵害。第2項列出四款判斷基準（目的及性質、著作之性質、質量及比例、對潛在市場與現在價值之影響）。利用人的身分（例如是學生）不是法定基準；學生的利用也可能不合理。","basis":"著作權法 §65","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4IP_05","course":"ip_law","term":"Y4S1","scopeWeek":6,"type":"mc","q":"甲把自己寫的歌的著作財產權全部讓與給乙。依著作權法，下列敘述何者正確？","options":{"A":"甲的著作人格權也一併移轉給乙","B":"乙可以任意把歌改成損害甲名譽的版本，甲無權禁止","C":"著作人格權專屬於著作人本身，不得讓與或繼承","D":"甲死亡以後，著作人格權由甲的繼承人繼承"},"answer":"C","core":"著作人格權｜專屬於著作人本身，不得讓與或繼承；著作財產權可以讓與。","explanation":"第21條：著作人格權專屬於著作人本身，不得讓與或繼承。著作人格權包括公開發表權、姓名表示權（第16條）及禁止他人以歪曲、割裂、竄改等方法改變著作致損害其名譽的權利（第17條）；讓與的只有著作財產權。","basis":"著作權法 §16、§17、§21","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4IP_06","course":"ip_law","term":"Y4S1","scopeWeek":6,"type":"mc","q":"自然人創作的著作，其著作財產權的存續期間，依著作權法第30條原則上為何？","options":{"A":"著作完成後五十年","B":"著作人生存期間及其死亡後五十年","C":"著作人生存期間及其死亡後七十年","D":"永久存續"},"answer":"B","core":"著作財產權的存續期間｜原則上為著作人生存期間及其死亡後五十年。","explanation":"第30條第1項：著作財產權，除本法另有規定外，存續於著作人之生存期間及其死亡後五十年；第2項：著作於著作人死亡後四十年至五十年間首次公開發表者，自公開發表時起存續十年。","basis":"著作權法 §30","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4IP_07","course":"ip_law","term":"Y4S1","scopeWeek":11,"type":"mc","q":"依專利法第22條，下列何者「不是」取得發明專利的要件？","options":{"A":"發明人必須是中華民國國民","B":"可供產業上利用（產業利用性）","C":"申請前沒有見於刊物、公開實施或為公眾所知悉（新穎性）","D":"不是所屬技術領域中具有通常知識者依申請前的先前技術所能輕易完成（進步性）"},"answer":"A","core":"發明專利的要件｜產業利用性、新穎性、進步性（法律沒有要求發明人的國籍）。","explanation":"第22條第1項：可供產業上利用之發明，無申請前已見於刊物、已公開實施、已為公眾所知悉等情事，得申請取得發明專利；第2項：為所屬技術領域中具有通常知識者依申請前之先前技術所能輕易完成時，仍不得取得發明專利。第21條：發明，指利用自然法則之技術思想之創作。","basis":"專利法 §21、§22","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4IP_08","course":"ip_law","term":"Y4S1","scopeWeek":11,"type":"mc","q":"下列關於專利權期限的敘述，何者正確？","options":{"A":"新型專利權：自公告日起算二十年","B":"設計專利權：自申請日起算十年","C":"發明專利權：自公告日起算十年","D":"發明專利權：自申請日起算二十年屆滿"},"answer":"D","core":"專利權期限｜發明 20 年、新型 10 年、設計 15 年，都自申請日起算。","explanation":"專利法第52條第3項：發明專利權期限，自申請日起算二十年屆滿；第114條：新型專利權期限，自申請日起算十年屆滿；第135條：設計專利權期限，自申請日起算十五年屆滿。","basis":"專利法 §52、§114、§135","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4IP_09","course":"ip_law","term":"Y4S1","scopeWeek":12,"type":"mc","q":"依專利法第58條第1項，發明專利權人除本法另有規定外，專有什麼權利？","options":{"A":"只有自己製造該物品的權利","B":"排除他人未經其同意而實施該發明的權利","C":"向使用該發明的消費者收稅的權利","D":"禁止任何人研究相同主題的權利"},"answer":"B","core":"專利權的效力｜排他權：排除他人未經同意而實施該發明。","explanation":"第58條第1項：發明專利權人，除本法另有規定外，專有排除他人未經其同意而實施該發明之權。第2項：物之發明之實施，指製造、為販賣之要約、販賣、使用或為上述目的而進口該物之行為。專利權是「排他」的權利，不是保證自己可以實施，也不能禁止一切研究。","basis":"專利法 §58","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4IP_10","course":"ip_law","term":"Y4S1","scopeWeek":13,"type":"mc","q":"下列關於商標的敘述，何者正確？","options":{"A":"商標權期間為十年，得申請延展，每次延展為十年","B":"商標只能以文字或圖形組成，聲音不能作為商標","C":"商標權自申請日起取得，期間二十年","D":"商標只要有人使用，不需要任何識別性"},"answer":"A","core":"商標｜具識別性的標識（文字、圖形、顏色、立體形狀、動態、全像圖、聲音等）；註冊公告日起取得，期間十年，可延展，每次十年。","explanation":"商標法第18條：商標指任何具有識別性之標識，得以文字、圖形、記號、顏色、立體形狀、動態、全像圖、聲音等或其聯合式所組成；識別性指足以使相關消費者認識為指示商品或服務來源，並與他人商品或服務相區別者。第33條：商標自註冊公告當日起取得商標權，期間十年；得申請延展，每次延展為十年。","basis":"商標法 §18、§33","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4IP_11","course":"ip_law","term":"Y4S1","scopeWeek":13,"type":"mc","q":"商標註冊以後，商標權人沒有正當事由迄未使用或繼續停止使用已滿一定期間，且也沒有被授權人使用。依商標法第63條，滿多久商標專責機關應依職權或據申請廢止其註冊？","options":{"A":"一年","B":"二年","C":"三年","D":"五年"},"answer":"C","core":"商標的廢止｜無正當事由迄未使用或繼續停止使用已滿三年者，應廢止註冊（被授權人有使用者不在此限）。","explanation":"第63條第1項第2款：無正當事由迄未使用或繼續停止使用已滿三年者，商標專責機關應依職權或據申請廢止其註冊；但被授權人有使用者，不在此限。","basis":"商標法 §63","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4IP_12","course":"ip_law","term":"Y4S1","scopeWeek":14,"type":"mc","q":"依營業秘密法第2條，下列何者「不是」營業秘密的要件？","options":{"A":"非一般涉及該類資訊的人所知","B":"因其秘密性而具有實際或潛在的經濟價值","C":"所有人已採取合理的保密措施","D":"已向經濟部智慧財產局登記"},"answer":"D","core":"營業秘密的要件｜秘密性、經濟價值、合理保密措施（不需要登記）。","explanation":"第2條：營業秘密指方法、技術、製程、配方、程式、設計或其他可用於生產、銷售或經營之資訊，而符合：一、非一般涉及該類資訊之人所知者；二、因其秘密性而具有實際或潛在之經濟價值者；三、所有人已採取合理之保密措施者。營業秘密不經登記，也正因為不公開才受保護。","basis":"營業秘密法 §2","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4IP_13","course":"ip_law","term":"Y4S1","scopeWeek":14,"type":"mc","q":"受雇人在職務上研究或開發出一項營業秘密，雙方的契約對歸屬沒有特別約定。依營業秘密法第3條，這項營業秘密歸誰所有？","options":{"A":"雇用人","B":"受雇人","C":"雇用人和受雇人共有","D":"國家"},"answer":"A","core":"營業秘密的歸屬｜職務上研發歸雇用人（契約另有約定從其約定）；非職務上研發歸受雇人。","explanation":"第3條第1項：受雇人於職務上研究或開發之營業秘密，歸雇用人所有，但契約另有約定者從其約定；第2項：非職務上研究或開發者歸受雇人，但利用雇用人的資源或經驗者，雇用人得於支付合理報酬後，於該事業使用該營業秘密。","basis":"營業秘密法 §3","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4LSO_01","course":"labor_social","term":"Y4S1","scopeWeek":2,"type":"mc","q":"依勞工保險條例第6條第1項，受僱於「僱用幾人以上」的公司、行號之員工，應以雇主為投保單位，全部參加勞工保險？","options":{"A":"一人","B":"三人","C":"五人","D":"十人"},"answer":"C","core":"勞保的強制加保｜受僱於僱用五人以上公司、行號等的員工，強制加保（未滿五人可依第8條自願加保）。","explanation":"勞工保險條例第6條第1項第2款：年滿十五歲以上、六十五歲以下，受僱於僱用五人以上公司、行號之員工，應以其雇主為投保單位，全部參加勞工保險。第8條第1項第2款：受僱於僱用未滿五人之第6條第1項第1款至第3款各業的員工，得準用本條例參加勞工保險。","basis":"勞工保險條例 §6、§8","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4LSO_02","course":"labor_social","term":"Y4S1","scopeWeek":2,"type":"mc","q":"勞工甲符合勞工保險條例第6條的強制加保資格，但投保單位沒有在甲到職當日列表通知保險人，而是在一週後才通知。依勞工保險條例第11條，甲的勞保效力從什麼時候開始？","options":{"A":"通知之翌日","B":"到職當日","C":"通知當月的一日","D":"試用期滿以後"},"answer":"A","core":"勞保效力的開始｜到職當日通知者自當日起算；非於到職當日通知者，自通知之翌日起算（投保單位另依第72條處罰、賠償勞工損失）。","explanation":"第11條：投保單位應於勞工到職當日列表通知保險人，保險效力自應為通知之當日起算；但非於到職當日通知者，除依第72條處罰外，保險效力之開始自通知之翌日起算。第72條第1項：未為勞工辦理投保手續者處罰鍰，勞工因此所受損失並應由投保單位依給付標準賠償。","basis":"勞工保險條例 §11、§72","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4LSO_03","course":"labor_social","term":"Y4S1","scopeWeek":3,"type":"mc","q":"下列關於全民健康保險的敘述，何者正確？","options":{"A":"全民健保是可以自由選擇是否加入的商業保險","B":"外國人一律不得參加全民健保","C":"保險對象看門診，一律不用負擔任何費用","D":"全民健保為強制性之社會保險"},"answer":"D","core":"全民健保｜強制性社會保險；符合資格的外國人也應參加；門診原則上自行負擔一定比例。","explanation":"全民健康保險法第1條第2項：本保險為強制性之社會保險。第9條：在臺灣地區領有居留證明文件，並在臺居留滿六個月、有一定雇主之受僱者或在臺出生之新生嬰兒，亦應參加。第43條第1項：保險對象原則上應自行負擔門診或急診費用之百分之二十（未經轉診至較高層級醫院者比例較高）。","basis":"全民健康保險法 §1、§9、§43","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4LSO_04","course":"labor_social","term":"Y4S1","scopeWeek":5,"type":"mc","q":"成年的甲在一家只有三名員工、已依法辦理商業登記的小吃店工作。依勞工職業災害保險及保護法，下列何者正確？","options":{"A":"員工未滿五人，雇主不必為甲參加職業災害保險","B":"雇主應以其為投保單位，為甲參加職業災害保險","C":"只有工廠的勞工才適用這部法律","D":"甲只能自己透過職業工會參加職業災害保險"},"answer":"B","core":"職災保險的強制加保｜受僱於領有執業證照、依法已辦理登記、設有稅籍等雇主的勞工，不論雇主僱用幾人，都要加保。","explanation":"勞工職業災害保險及保護法第6條第1項第1款：年滿十五歲以上，受僱於領有執業證照、依法已辦理登記、設有稅籍或經中央主管機關依法核發聘僱許可之雇主的勞工，應以其雇主為投保單位，參加本保險。和勞工保險條例第6條「僱用五人以上」不同，職災保險沒有人數門檻。職業工會加保（第7條）是給無一定雇主或自營作業者。","basis":"勞工職業災害保險及保護法 §6、§7","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4LSO_05","course":"labor_social","term":"Y4S1","scopeWeek":5,"type":"mc","q":"依勞工職業災害保險及保護法第13條，受僱於已依法辦理登記之雇主的勞工，其職業災害保險效力原則上從什麼時候開始？","options":{"A":"到職當日","B":"雇主通知保險人之翌日","C":"到職滿一個月","D":"第一次繳納保險費的那一天"},"answer":"A","core":"職災保險的效力｜自到職當日起算，至離職當日停止（和勞保「遲通知者自通知翌日起算」不同）。","explanation":"第13條第1項本文：符合第6條規定之勞工，其保險效力之開始自到職當日起算，至離職當日停止。例外是勞工在雇主領有執業證照、辦理登記或設有稅籍之前到職者，自雇主符合條件之當日起算。","basis":"勞工職業災害保險及保護法 §13","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4LSO_06","course":"labor_social","term":"Y4S1","scopeWeek":5,"type":"mc","q":"被保險人遭遇職業傷病不能工作，致未能取得原有薪資，正在治療中。依勞工職業災害保險及保護法第42條，自不能工作之日起算第幾日起，得請領傷病給付？","options":{"A":"不能工作的當日","B":"第二日","C":"第三日","D":"第四日"},"answer":"D","core":"職災傷病給付｜自不能工作之日起算第四日起請領；前二個月按平均月投保薪資發給，第三個月起按百分之七十，最長二年。","explanation":"第42條第1項：自不能工作之日起算第四日起，得請領傷病給付；第2項：前二個月按被保險人平均月投保薪資發給，第三個月起按平均月投保薪資百分之七十發給，每半個月給付一次，最長以二年為限。","basis":"勞工職業災害保險及保護法 §42","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4LSO_07","course":"labor_social","term":"Y4S1","scopeWeek":6,"type":"mc","q":"依就業保險法第11條，下列何者「不是」請領失業給付的條件？","options":{"A":"非自願離職","B":"離職辦理退保當日前三年內，保險年資合計滿一年以上","C":"離職前在同一雇主連續工作滿五年","D":"向公立就業服務機構辦理求職登記，自求職登記之日起十四日內仍無法推介就業或安排職業訓練"},"answer":"C","core":"失業給付的請領條件｜非自願離職、退保前三年內年資滿一年、有工作能力及意願、辦理求職登記且十四日內無法推介就業或安排訓練。","explanation":"就業保險法第11條第1項第1款：被保險人於非自願離職辦理退保當日前三年內，保險年資合計滿一年以上，具有工作能力及繼續工作意願，向公立就業服務機構辦理求職登記，自求職登記之日起十四日內仍無法推介就業或安排職業訓練。法律沒有要求在同一雇主工作滿五年。","basis":"就業保險法 §11","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4LSO_08","course":"labor_social","term":"Y4S1","scopeWeek":6,"type":"mc","q":"申請人離職退保時未滿四十五歲，也沒有身心障礙證明，而且沒有延長給付的情形。依就業保險法第16條第1項，失業給付如何發給？","options":{"A":"按離職退保當月起前六個月平均月投保薪資百分之六十按月發給，最長六個月","B":"按平均月投保薪資百分之六十按月發給，最長九個月","C":"按平均月投保薪資百分之八十按月發給，最長六個月","D":"按平均月投保薪資百分之五十按月發給，最長十二個月"},"answer":"A","core":"失業給付的金額與期間｜前六個月平均月投保薪資的 60%，最長六個月；45 歲以上或領有身心障礙證明者最長九個月。","explanation":"第16條第1項：失業給付按申請人離職辦理本保險退保之當月起前六個月平均月投保薪資百分之六十按月發給，最長發給六個月；但退保時已年滿四十五歲或領有身心障礙證明者，最長九個月。第2項：經濟不景氣等緊急情事，中央主管機關得延長，最長不得超過十二個月。","basis":"就業保險法 §16","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4LSO_09","course":"labor_social","term":"Y4S1","scopeWeek":7,"type":"mc","q":"依長期照顧服務法第9條，下列何者「不是」法定的長照服務提供方式？","options":{"A":"居家式","B":"由雇主提供的員工團體保險","C":"社區式","D":"機構住宿式"},"answer":"B","core":"長照服務的提供方式｜居家式、社區式、機構住宿式、家庭照顧者支持服務、其他經中央主管機關公告的方式。","explanation":"長期照顧服務法第9條第1項：長照服務依其提供方式，區分為居家式（到宅提供服務）、社區式（日間照顧、家庭托顧、臨時住宿、團體家屋、小規模多機能等）、機構住宿式（全時照顧或夜間住宿）、家庭照顧者支持服務，以及其他經中央主管機關公告之服務方式。","basis":"長期照顧服務法 §9","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4LSO_10","course":"labor_social","term":"Y4S1","scopeWeek":10,"type":"mc","q":"依社會救助法，下列敘述何者正確？","options":{"A":"只要家裡有人有工作，就不能被認定為低收入戶","B":"最低生活費由各鄉（鎮、市）公所自行決定","C":"社會救助只有現金給付一種","D":"社會救助分生活扶助、醫療補助、急難救助及災害救助"},"answer":"D","core":"社會救助｜四種：生活扶助、醫療補助、急難救助、災害救助；低收入戶看家庭總收入平均每人每月是否在最低生活費以下及家庭財產。","explanation":"社會救助法第2條：社會救助分生活扶助、醫療補助、急難救助及災害救助。第4條第1項：低收入戶指家庭總收入平均分配全家人口，每人每月在最低生活費以下，且家庭財產未超過公告一定金額者（有人工作不當然排除）；第2項：最低生活費由中央、直轄市主管機關參照當地區最近一年每人可支配所得中位數百分之六十定之。","basis":"社會救助法 §2、§4","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4LSO_11","course":"labor_social","term":"Y4S1","scopeWeek":11,"type":"mc","q":"某民營事業機構員工總人數為一百人。依身心障礙者權益保障法第38條第2項，該機構進用具有就業能力之身心障礙者人數，不得低於多少？","options":{"A":"員工總人數百分之三","B":"員工總人數百分之五","C":"員工總人數百分之一，且不得少於一人","D":"民營事業沒有進用義務"},"answer":"C","core":"身心障礙者定額進用｜公部門員工 34 人以上：不低於 3%；私立學校、團體、民營事業 67 人以上：不低於 1% 且不少於一人。","explanation":"第38條第1項：各級政府機關、公立學校及公營事業機構員工總人數在三十四人以上者，進用人數不得低於員工總人數百分之三；第2項：私立學校、團體及民營事業機構員工總人數在六十七人以上者，不得低於員工總人數百分之一，且不得少於一人。","basis":"身心障礙者權益保障法 §38","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4LSO_12","course":"labor_social","term":"Y4S1","scopeWeek":12,"type":"mc","q":"依兒童及少年福利與權益保障法第2條，下列敘述何者正確？","options":{"A":"兒童指未滿十四歲之人","B":"兒童指未滿十二歲之人；少年指十二歲以上未滿十八歲之人","C":"少年指十八歲以上未滿二十歲之人","D":"本法只保護兒童，不包括少年"},"answer":"B","core":"兒童及少年的定義｜兒童：未滿十二歲；少年：十二歲以上未滿十八歲；本法保護未滿十八歲之人。","explanation":"第2條：本法所稱兒童及少年，指未滿十八歲之人；所稱兒童，指未滿十二歲之人；所稱少年，指十二歲以上未滿十八歲之人。","basis":"兒童及少年福利與權益保障法 §2","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4LSO_13","course":"labor_social","term":"Y4S1","scopeWeek":13,"type":"mc","q":"被保險人對勞工職業災害保險的保險人所核定的給付案件有爭議。依勞工職業災害保險及保護法第5條，下列何者正確？","options":{"A":"應自行政處分達到之翌日起六十日內，向中央主管機關申請審議；不服審議結果，再提起訴願及行政訴訟","B":"應直接向普通法院提起民事訴訟，不必經過任何行政程序","C":"應先到保險人所在地的鄉鎮市公所調解，調解不成才能起訴","D":"保險人的核定是最終決定，不得再爭執"},"answer":"A","core":"社會保險的爭議救濟｜先申請爭議審議，再訴願、行政訴訟（勞保、健保也是先審議）。","explanation":"勞工職業災害保險及保護法第5條第1項：對保險人核定之案件有爭議時，應自行政處分達到之翌日起六十日內，向中央主管機關申請審議，對於爭議審議結果不服時，得提起訴願及行政訴訟。全民健康保險法第6條也規定先申請審議，不服再訴願或行政訴訟。","basis":"勞工職業災害保險及保護法 §5；全民健康保險法 §6","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4MAR_01","course":"maritime","term":"Y4S2","scopeWeek":2,"type":"mc","q":"甲將自己所有的貨輪賣給乙，雙方已作成書面，並經航政主管機關蓋印證明，但還沒有辦理所有權移轉登記。依海商法，下列敘述何者正確？","options":{"A":"讓與尚未生效，要登記以後才生效力","B":"船舶是不動產，沒有登記的讓與無效","C":"讓與已經生效，但沒有登記不得對抗第三人","D":"讓與已經生效，而且可以對抗任何第三人"},"answer":"C","core":"船舶所有權的讓與｜書面＋蓋印證明就生效；登記是對抗要件。","explanation":"第8條：船舶所有權的讓與，要作成書面並經蓋印證明，才生效力；第9條：所有權移轉非經登記，不得對抗第三人。船舶依第6條原則上適用民法關於動產的規定，不是不動產。","basis":"海商法 §6、§8、§9","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4MAR_02","course":"maritime","term":"Y4S2","scopeWeek":2,"type":"mc","q":"下列關於船舶抵押權的敘述，何者正確？","options":{"A":"船舶適用動產的規定，所以不能設定抵押權","B":"抵押權的設定應以書面為之，非經登記不得對抗第三人","C":"抵押權只要口頭約定，就可以對抗第三人","D":"抵押權沒有登記，設定行為就無效"},"answer":"B","core":"船舶抵押權｜書面設定；登記才能對抗第三人。","explanation":"船舶雖然原則上適用動產的規定（第6條），海商法另外特別規定可以設定抵押權：第33條要求以書面設定，第36條規定非經登記不得對抗第三人。登記是對抗要件，不是生效要件。","basis":"海商法 §6、§33、§36","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4MAR_03","course":"maritime","term":"Y4S2","scopeWeek":3,"type":"mc","q":"貨輪發航前及發航時，運送人已經為必要的注意及措置，使船舶有安全航行的能力；發航以後，船舶卻突然失去航行能力，船上的貨物因此毀損。依海商法第62條，運送人原則上：","options":{"A":"不論有沒有過失，都要負全部賠償責任","B":"要和託運人平均分擔損失","C":"只負一半的賠償責任","D":"不負賠償責任，但要由運送人負舉證責任"},"answer":"D","core":"堪航能力｜發航前及發航時的注意義務；發航後突失航行能力所致的損害，運送人不負責（由運送人舉證）。","explanation":"第62條第1項要求運送人於發航前及發航時，為必要的注意及措置，使船舶有安全航行的能力；第2項：船舶於發航後因突失航行能力所致的毀損或滅失，運送人不負賠償責任；第3項：運送人要主張免責，應負舉證之責。","basis":"海商法 §62","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4MAR_04","course":"maritime","term":"Y4S2","scopeWeek":3,"type":"mc","q":"船長在航行中操作船舶時判斷錯誤（航行上的過失），導致船上的貨物毀損。依海商法第69條，運送人對這項毀損原則上：","options":{"A":"不負賠償責任","B":"應負全部賠償責任","C":"只要託運人證明船長有過失，就要負責","D":"和託運人平均分擔"},"answer":"A","core":"運送人的免責事由｜船長、海員、引水人或運送人的受僱人於航行或管理船舶的過失，運送人不負賠償責任。","explanation":"第69條第1款。要分清楚：對「貨物本身」的裝載、卸載、搬移、堆存、保管、運送及看守，第63條仍要求運送人為必要的注意及處置；免責的是「航行或管理船舶」的過失。","basis":"海商法 §63、§69①","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4MAR_05","course":"maritime","term":"Y4S2","scopeWeek":4,"type":"mc","q":"甲以「以船舶之全部供運送為目的」的運送契約（傭船契約）向乙租船運貨，乙另外簽發了載貨證券，這張載貨證券後來轉讓給丙。依海商法第60條第2項，運送人乙和丙之間的關係，應依什麼決定？","options":{"A":"甲乙之間的傭船契約","B":"載貨證券的記載","C":"船長的航海日誌","D":"甲丙之間的買賣契約"},"answer":"B","core":"載貨證券的文義性｜運送人和託運人以外的載貨證券持有人之間，依載貨證券的記載。","explanation":"第60條第2項：以船舶之全部或一部供運送為目的之運送契約另行簽發載貨證券者，運送人與託運人以外載貨證券持有人間的關係，依載貨證券的記載。第1項並規定民法關於提單的規定（第627～630條）準用於載貨證券。","basis":"海商法 §60","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4MAR_06","course":"maritime","term":"Y4S2","scopeWeek":5,"type":"mc","q":"船舶航行中遇到暴風，船長為了保全船舶和全部貨物的共同安全，故意而且合理地把一部分貨物拋進海裡。依海商法，下列敘述何者正確？","options":{"A":"這是被拋棄貨物的貨主自己的損失，由他自行承擔","B":"船長的拋棄構成侵權行為，應由船長個人賠償","C":"這是共同海損，由各利害關係人按被保存財產價值與共同海損總額的比例分擔","D":"由運送人單獨負擔全部損失"},"answer":"C","core":"共同海損｜為求共同危險中全體財產的安全所為故意及合理的處分；犧牲由各利害關係人按比例分擔。","explanation":"第110條定義共同海損；第111條：以各被保存財產價值與共同海損總額的比例，由各利害關係人分擔；因共同海損行為所犧牲而獲補償的財產，也要參與分擔。","basis":"海商法 §110、§111","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4MAR_07","course":"maritime","term":"Y4S2","scopeWeek":6,"type":"mc","q":"漁船對一艘遇難的貨輪及船上貨物施以救助，但最後沒有任何救助效果，也沒有損害環境之虞的情形。依海商法第103條第1項，漁船可以請求救助報酬嗎？","options":{"A":"可以，按實際支出的費用請求全額報酬","B":"可以，請求貨輪價值的一半","C":"不可以依該項請求，因為報酬以救助有效果為要件","D":"可以，海難救助一律有固定的報酬"},"answer":"C","core":"海難救助的報酬｜對船舶或船上財物施以救助「而有效果」，才得按效果請求相當的報酬。","explanation":"第103條第1項。第2項另有例外：施救的船舶或貨物有損害環境之虞時，施救人得向船舶所有人請求與實際支出費用同額的報酬（題目已排除這種情形）。","basis":"海商法 §103","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4MAR_08","course":"maritime","term":"Y4S2","scopeWeek":7,"type":"mc","q":"海上保險的保險事故發生後，被保險人沒有採取必要行為去避免或減輕保險標的的損失，使損失擴大。依海商法第130條，保險人對擴大的損失：","options":{"A":"仍應負全部賠償責任","B":"只負一半的賠償責任","C":"得解除契約並沒收全部保險費","D":"不負賠償責任"},"answer":"D","core":"海上保險｜被保險人的損失減輕義務；沒有履行而擴大的損失，保險人不負賠償責任。","explanation":"第130條第1項。同條第2項：保險人對要保人或被保險人為履行這項義務所生的費用，負償還之責，償還數額和賠償金額合計雖然超過保險標的價值，仍應償還；第3項：以保險金額為限（保險金額不及標的價值時按比例）。","basis":"海商法 §130","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4MAR_09","course":"maritime","term":"Y4S2","scopeWeek":10,"type":"mc","q":"依中華民國領海及鄰接區法、中華民國專屬經濟海域及大陸礁層法，下列敘述何者正確？","options":{"A":"領海為自基線起至其外側二十四浬間的海域","B":"鄰接區為鄰接領海外側至距離基線二十四浬間的海域","C":"專屬經濟海域為鄰接領海外側至距離領海基線一百浬間的海域","D":"領海基線一律採用正常基線"},"answer":"B","core":"海域的範圍｜領海 12 浬；鄰接區到距基線 24 浬；專屬經濟海域到距領海基線 200 浬；基線以直線基線為原則。","explanation":"領海及鄰接區法第3條：領海為自基線起至外側十二浬；第14條：鄰接區為鄰接領海外側至距離基線二十四浬；第4條：基線採直線基線為原則、正常基線為例外的混合基線法。專屬經濟海域及大陸礁層法第2條：專屬經濟海域到距離領海基線二百浬。","basis":"中華民國領海及鄰接區法 §3、§4、§14；中華民國專屬經濟海域及大陸礁層法 §2","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4MAR_10","course":"maritime","term":"Y4S2","scopeWeek":11,"type":"mc","q":"依船員法，下列關於船員勞動條件的敘述，何者正確？","options":{"A":"船員正常工作時間，以每週工作總時數四十四小時為準","B":"雇用人得預扣船員報酬，作為船員可能造成損害的賠償費用","C":"船員在船上服務滿一年，雇用人應給予有給年休十天","D":"船長不限於中華民國國民"},"answer":"A","core":"船員的勞動條件｜每週 44 小時為準（航行當值輪班除外）；不得預扣報酬作賠償；服務滿一年有給年休 30 天；船長應為中華民國國民。","explanation":"船員法第32條第1項：正常工作時間以每週工作總時數四十四小時為準，但因航行需要參加航行當值輪班者不在此限。第26條第2項：雇用人不得預扣船員報酬作為賠償費用；第37條：服務滿一年有給年休三十天；第5條第2項：船長應為中華民國國民。","basis":"船員法 §5、§26、§32、§37","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4MAR_11","course":"maritime","term":"Y4S2","scopeWeek":13,"type":"mc","q":"一艘船舶漏油污染海洋，造成沿岸漁民的損害。依海洋污染防治法，下列敘述何者正確？","options":{"A":"船舶所有人應負賠償責任，賠償請求權人並得直接向責任保險人請求賠償","B":"只有船長個人要負賠償責任","C":"漁民只能請求國家賠償","D":"漁民必須先證明船長是故意的，才能請求賠償"},"answer":"A","core":"海洋污染的損害賠償｜船舶所有人負賠償責任；請求權人得直接向責任保險人請求。","explanation":"海洋污染防治法第36條第1項：船舶對海洋污染產生的損害，船舶所有人應負賠償責任；第2項：一定噸位以上的船舶應投保責任保險或提供擔保；第37條：賠償請求權人得直接向責任保險人請求賠償，或就擔保求償。","basis":"海洋污染防治法 §36、§37","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4TAX_01","course":"tax_law","term":"Y4S1","scopeWeek":1,"type":"mc","q":"依憲法第19條與納稅者權利保護法第3條，下列關於租稅法律主義的敘述，何者正確？","options":{"A":"財政部的解釋函令，可以增加法律沒有明定的納稅義務","B":"地方政府不得以自治條例作為課稅依據","C":"主管機關的行政規則及解釋函令，不得增加法律所未明定的納稅義務或減免稅捐","D":"只要行政院院會通過，就可以直接開徵新稅"},"answer":"C","core":"租稅法律主義｜納稅的權利與義務要有法律依據；行政規則、解釋函令只能解釋法律原意與技術性、細節性事項。","explanation":"憲法第19條：人民有依法律納稅之義務。納稅者權利保護法第3條第1項：納稅者有依法律納稅之權利與義務；第2項：在直轄市、縣（市）及鄉（鎮、市），法律包括自治條例；第3項：行政規則及解釋函令僅得解釋法律原意、規範執行法律所必要之技術性、細節性事項，不得增加法律所未明定之納稅義務或減免稅捐。","basis":"憲法 §19；納稅者權利保護法 §3","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4TAX_02","course":"tax_law","term":"Y4S1","scopeWeek":2,"type":"mc","q":"依所得稅法第2條，下列敘述何者正確？","options":{"A":"非中華民國境內居住的個人有中華民國來源所得者，除另有規定外，其應納稅額分別就源扣繳","B":"個人應就其全球所得，依所得稅法課徵綜合所得稅","C":"非中華民國境內居住的個人，其中華民國來源所得一律免稅","D":"只有中華民國國民才要課徵綜合所得稅"},"answer":"A","core":"綜合所得稅的課稅範圍｜有中華民國來源所得的個人，就中華民國來源所得課稅；非居住者原則上就源扣繳。","explanation":"所得稅法第2條第1項：凡有中華民國來源所得之個人，應就其中華民國來源之所得課徵綜合所得稅（不限國籍）；第2項：非中華民國境內居住之個人有中華民國來源所得者，除本法另有規定外，其應納稅額分別就源扣繳。","basis":"所得稅法 §2","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4TAX_03","course":"tax_law","term":"Y4S1","scopeWeek":3,"type":"mc","q":"你在便利商店買了一杯飲料，價格裡已經含有營業稅。依加值型及非加值型營業稅法第2條，這筆交易的營業稅納稅義務人是誰？","options":{"A":"買飲料的消費者","B":"便利商店的店員","C":"飲料的運送業者","D":"銷售貨物的營業人（便利商店）"},"answer":"D","core":"營業稅的納稅義務人｜法律上是銷售貨物或勞務的營業人；消費者只是經濟上的負擔者。","explanation":"營業稅法第1條：在中華民國境內銷售貨物或勞務及進口貨物，均應課徵營業稅；第2條第1款：銷售貨物或勞務之營業人為納稅義務人（進口貨物是收貨人或持有人）。稅額轉嫁在價格裡，是經濟上的負擔，不改變法律上的納稅義務人。","basis":"加值型及非加值型營業稅法 §1、§2","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4TAX_04","course":"tax_law","term":"Y4S1","scopeWeek":4,"type":"mc","q":"依遺產及贈與稅法，下列關於納稅義務人的敘述，何者正確？","options":{"A":"贈與稅的納稅義務人原則上是受贈人","B":"遺產稅的納稅義務人為繼承人及受遺贈人；沒有繼承人者，為遺產管理人","C":"遺產稅的納稅義務人一律是被繼承人的配偶","D":"贈與人行蹤不明時，贈與稅就免徵"},"answer":"B","core":"遺產稅、贈與稅的納稅義務人｜遺產稅：繼承人及受遺贈人（無繼承人：遺產管理人）；贈與稅：贈與人（例外才是受贈人）。","explanation":"第6條第1項：遺產稅之納稅義務人為繼承人及受遺贈人，無繼承人者為遺產管理人。第7條第1項：贈與稅之納稅義務人為贈與人；但贈與人行蹤不明、逾期未繳且境內無財產可供執行、或死亡時贈與稅尚未核課者，以受贈人為納稅義務人。","basis":"遺產及贈與稅法 §6、§7","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4TAX_05","course":"tax_law","term":"Y4S1","scopeWeek":4,"type":"mc","q":"甲以顯著低於市價的價格，把自己的房屋賣給朋友乙（兩人不是親屬）。依遺產及贈與稅法第5條，下列何者正確？","options":{"A":"以顯著不相當的代價讓與財產，其差額部分以贈與論，課徵贈與稅","B":"只要訂有買賣契約，就不可能涉及贈與稅","C":"房屋的全部價值都以贈與論","D":"贈與稅原則上由乙繳納"},"answer":"A","core":"以贈與論｜以顯著不相當的代價讓與財產，差額部分以贈與論。","explanation":"第5條第2款：以顯著不相當之代價讓與財產、免除或承擔債務者，其差額部分以贈與論。贈與稅的納稅義務人原則上是贈與人甲（第7條）。（若是二親等以內親屬間的買賣，另有第5條第6款的規定，本題不涉及。）","basis":"遺產及贈與稅法 §5②、§7","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4TAX_06","course":"tax_law","term":"Y4S1","scopeWeek":5,"type":"mc","q":"在中華民國境內居住的個人甲，2025年買進一間房屋（不是自住，也沒有調職、非自願離職等特殊情形），持有一年後出售而有交易所得。依所得稅法第14條之4，這筆房屋、土地交易所得適用的稅率是多少？","options":{"A":"百分之十五","B":"百分之二十","C":"百分之三十五","D":"百分之四十五"},"answer":"D","core":"房地合一稅｜持有期間越短稅率越高：二年以內 45%、超過二年未逾五年 35%、超過五年未逾十年 20%、超過十年 15%。","explanation":"所得稅法第4條之4：民國105年1月1日以後取得的房屋、土地，交易所得依第14條之4等規定課稅。第14條之4第3項第1款第1目：境內居住的個人持有期間在二年以內者，稅率為百分之四十五。調職、非自願離職等情形另有百分之二十的稅率，題目已排除。","basis":"所得稅法 §4-4、§14-4","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4TAX_07","course":"tax_law","term":"Y4S1","scopeWeek":6,"type":"mc","q":"納稅義務人依法應自行申報繳納的稅捐，已經在規定期間內申報，而且沒有故意以詐欺或其他不正當方法逃漏稅捐。依稅捐稽徵法第21條，其核課期間為多久？","options":{"A":"二年","B":"五年","C":"七年","D":"十年"},"answer":"B","core":"核課期間｜已依限申報且無故意逃漏：五年；未依限申報或故意逃漏：七年。","explanation":"稅捐稽徵法第21條第1項第1款：五年；第3款：未於規定期間內申報，或故意以詐欺或其他不正當方法逃漏稅捐者，七年。第2項：核課期間內未經發現者，以後不得再補稅處罰。","basis":"稅捐稽徵法 §21","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4TAX_08","course":"tax_law","term":"Y4S1","scopeWeek":7,"type":"mc","q":"依納稅者權利保護法第4條，下列敘述何者正確？","options":{"A":"基本生活所需的費用，由各縣市政府自行決定","B":"只要是生活費，不論金額多少都不得課稅","C":"納稅者為維持自己及受扶養親屬享有符合人性尊嚴之基本生活所需的費用，不得加以課稅","D":"基本生活所需費用的標準，每十年才檢討一次"},"answer":"C","core":"基本生活費不課稅｜維持符合人性尊嚴之基本生活所需的費用，不得課稅；標準由中央主管機關每年公告、檢討。","explanation":"第4條第1項：納稅者為維持自己及受扶養親屬享有符合人性尊嚴之基本生活所需之費用，不得加以課稅；第2項：由中央主管機關參照最近一年全國每人可支配所得中位數百分之六十定之，並應於每年定期公告及檢討。","basis":"納稅者權利保護法 §4","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4TAX_09","course":"tax_law","term":"Y4S1","scopeWeek":10,"type":"mc","q":"甲收到核定稅額通知書，上面載有應補徵稅額，甲不服。依稅捐稽徵法，下列關於救濟程序的敘述，何者正確？","options":{"A":"應先申請復查（繳款書送達後，於繳納期間屆滿之翌日起三十日內）；對復查決定不服，再提起訴願及行政訴訟","B":"可以直接向行政法院起訴，不必申請復查","C":"應先提起訴願，對訴願決定不服再申請復查","D":"申請復查的期間是收到通知書後一年內"},"answer":"A","core":"稅務救濟｜復查 → 訴願 → 行政訴訟；有應納或應補徵稅額者，於繳納期間屆滿之翌日起三十日內申請復查。","explanation":"稅捐稽徵法第35條第1項第1款：依核定稅額通知書所載有應納稅額或應補徵稅額者，應於繳款書送達後，於繳納期間屆滿之翌日起三十日內申請復查。第38條第1項：對復查決定不服，得依法提起訴願及行政訴訟。第35條第5項：稽徵機關逾二個月未作復查決定，可以逕行提起訴願。","basis":"稅捐稽徵法 §35、§38","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4TAX_10","course":"tax_law","term":"Y4S1","scopeWeek":12,"type":"mc","q":"納稅者為了獲得租稅利益，違背稅法的立法目的，濫用法律形式，以非常規交易規避租稅構成要件的該當（租稅規避）。依納稅者權利保護法第7條，下列何者正確？","options":{"A":"只要法律形式合法，稽徵機關就不能補稅","B":"一律以逃漏稅捐處罰","C":"稽徵機關仍依與實質經濟利益相當的法律形式課稅，並加徵滯納金及利息","D":"租稅規避的事實，由納稅者負舉證責任"},"answer":"C","core":"租稅規避｜依實質經濟利益相當的法律形式成立租稅請求權，加徵滯納金及利息；原則上不另課逃漏稅捐的處罰；稽徵機關負舉證責任。","explanation":"第7條第3項：為租稅規避者，稽徵機關仍根據與實質上經濟利益相當之法律形式，成立租稅上請求權，並加徵滯納金及利息；第4項：稽徵機關就其事實負舉證責任（第5項：納稅者的協力義務不因此免除）；第8項：不得另課予逃漏稅捐之處罰，但納稅者對重要事項隱匿或為虛偽不實陳述、提供不正確資料，致短漏核定者，不在此限。","basis":"納稅者權利保護法 §7","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4TAX_11","course":"tax_law","term":"Y4S1","scopeWeek":13,"type":"mc","q":"甲把自己所有的房屋出租給乙居住，房屋上沒有設定地上權或典權。依房屋稅條例第4條，房屋稅原則上向誰徵收？","options":{"A":"承租人乙","B":"甲乙各負擔一半","C":"實際居住在房屋裡的人","D":"房屋所有人甲"},"answer":"D","core":"房屋稅的納稅義務人｜原則上向房屋所有人徵收（設有典權者向典權人；以地上權設定的使用權房屋向使用權人）。","explanation":"房屋稅條例第4條第1項：房屋稅向房屋所有人徵收之；以土地設定地上權之使用權房屋，向該使用權人徵收之；設有典權者，向典權人徵收之。出租不改變納稅義務人。","basis":"房屋稅條例 §4","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"},{"id":"Y4TAX_12","course":"tax_law","term":"Y4S1","scopeWeek":14,"type":"mc","q":"總機構在中華民國境內的營利事業，在國外也有所得，而且已依所得來源國稅法繳納了所得稅。依所得稅法第3條，下列何者正確？","options":{"A":"只要就中華民國境內的所得課徵營利事業所得稅","B":"應就境內外全部營利事業所得合併課稅；國外已繳的稅可依規定扣抵，但扣抵數有上限","C":"國外所得一律免稅","D":"國外已繳的稅可以全額退還"},"answer":"B","core":"國際租稅｜總機構在境內：境內外全部所得合併課稅；國外已納稅額可扣抵，以加計國外所得而增加的國內應納稅額為限。","explanation":"所得稅法第3條第2項：總機構在中華民國境內者，應就其中華民國境內外全部營利事業所得，合併課徵營利事業所得稅；來自境外之所得已依所得來源國稅法繳納者，得提出納稅憑證並經簽證後扣抵；扣抵之數不得超過因加計其國外所得，而依國內適用稅率計算增加之結算應納稅額。","basis":"所得稅法 §3","status":"Y4_CROSS_REVIEWED","source":"BB_Y4"}],"courseMap":{"const_1":{"term":"Y1S1","name":"憲法（上）","exam":"mc5","status":"INSUFFICIENT"},"crim_gen1":{"term":"Y1S1","name":"刑法總則（一）","exam":"mc5","status":"ENABLED"},"civ_general":{"term":"Y1S1","name":"民法總則","exam":"mc5","status":"ENABLED"},"const_2":{"term":"Y1S2","name":"憲法（下）","exam":"mc5","status":"INSUFFICIENT"},"crim_gen2":{"term":"Y1S2","name":"刑法總則（二）","exam":"mc5","status":"ENABLED"},"oblig_gen1":{"term":"Y1S2","name":"民法債編總論（一）","exam":"mc5","status":"ENABLED"},"admin_law":{"term":"Y2S1","name":"行政法","exam":"mc5","status":"ENABLED"},"crim_spec":{"term":"Y2S1","name":"刑法分則","exam":"mc5","status":"ENABLED"},"property":{"term":"Y2S1","name":"民法物權","exam":"mc5","status":"ENABLED"},"oblig_gen2":{"term":"Y2S1","name":"民法債編總論（二）","exam":"mc5","status":"ENABLED"},"oblig_spec":{"term":"Y2S2","name":"民法債編各論","exam":"mc5","status":"ENABLED"},"family_law":{"term":"Y2S2","name":"民法身分法","exam":"mc5","status":"ENABLED"},"admin_remedy":{"term":"Y2S2","name":"行政救濟法","exam":"mc5","status":"INSUFFICIENT"},"legal_english":{"term":"Y2S2","name":"法學英文／英美法","exam":"mc5","status":"INSUFFICIENT"},"civpro_1":{"term":"Y3S1","name":"民事訴訟法甲上","exam":"mc5","status":"INSUFFICIENT"},"crimpro":{"term":"Y3S1","name":"刑事訴訟法","exam":"mc5","status":"ENABLED"},"company_law":{"term":"Y3S1","name":"商事法總論及公司法","exam":"mc5","status":"INSUFFICIENT"},"securities":{"term":"Y3S1","name":"證券交易法","exam":"mc5","status":"ENABLED"},"civpro_2":{"term":"Y3S2","name":"民事訴訟法甲下","exam":"mc5","status":"INSUFFICIENT"},"insurance":{"term":"Y3S2","name":"保險法","exam":"mc5","status":"INSUFFICIENT"},"negotiable":{"term":"Y3S2","name":"票據及支付工具法","exam":"mc5","status":"INSUFFICIENT"},"labor_law":{"term":"Y3S2","name":"勞動法","exam":"mc5","status":"INSUFFICIENT"},"enforcement":{"term":"Y4S1","name":"強制執行法","exam":"mc5","status":"ENABLED"},"legal_ethics":{"term":"Y4S1","name":"法律倫理","exam":"mc5","status":"ENABLED"},"ip_law":{"term":"Y4S1","name":"智慧財產權法","exam":"mc5","status":"ENABLED"},"labor_social":{"term":"Y4S1","name":"勞動社會法","exam":"mc5","status":"ENABLED"},"tax_law":{"term":"Y4S1","name":"財稅法","exam":"mc5","status":"ENABLED"},"crim_judgment_sem":{"term":"Y4S1","name":"刑事判決研討","exam":"mc5","status":"ENABLED"},"public_judgment_sem":{"term":"Y4S1","name":"公法判決研討","exam":"mc5","status":"ENABLED"},"legal_research":{"term":"Y4S2","name":"法律專題研究","exam":"none","status":"NO_EXAM"},"legal_practice":{"term":"Y4S2","name":"法律實習或法律扶助實務","exam":"none","status":"NO_EXAM"},"maritime":{"term":"Y4S2","name":"海商法與海洋法","exam":"mc5","status":"ENABLED"}}};
